@check("narrative", "the mover is split off a floor action, both chambers' ways",
       needs=("narrative",))
def _split_mover(narrative):
    """The House writes the mover last in parentheses; the Senate writes it
    first with the verb folded in. Before split_mover the Senate name stayed
    inside the motion, so a voice vote was headed "Sen. Abbas Moved Laid on
    Table" as if that were the question put."""
    s = narrative.split_mover
    assert s("Lay on Table (Rep. K. Rice)") == ("Lay on Table", "Rep. K. Rice")
    assert s("Sen. Abbas Moved Laid on Table") == ("Laid on Table", "Sen. Abbas")
    assert s("Sen. Fuller Clark Moved to Concur with the House Amendment") == \
        ("Concur with the House Amendment", "Sen. Fuller Clark")
    assert s("Sen. Innis Accedes to House Request for Committee of Conference") == \
        ("Accedes to House Request for Committee of Conference", "Sen. Innis")
    assert s("Sen. Birdsell moved to call the question") == \
        ("call the question", "Sen. Birdsell")
    assert s("Ought to Pass") == ("Ought to Pass", "")
    return "ok", "House parenthetical and Senate leading name both split"


@check("narrative", "real docket lines classify correctly", needs=("narrative",))
def _classify(narrative):
    wrong = []
    for want, line in DOCKET_LINES:
        got = narrative.classify(line)["_type"]
        if got != want:
            wrong.append(f"{want}->{got}: {line[:44]}")
    assert not wrong, "; ".join(wrong)
    return "ok", f"{len(DOCKET_LINES)} lines, every type as expected"


@check("narrative", "amendments stage by what the line says", needs=("narrative",))
def _amend_stage(narrative):
    cases = [("Amendment # 2026-0503h: AA VV 03/06/2026", "floor"),
             ("Committee Amendment # 2026-0777h, AA, VV; 03/06/2026", "committee"),
             ("Enrolled Bill Amendment # 2026-2001e Adopted, VV, "
              "(In recess 06/26/2026)", "governor")]
    wrong = []
    for line, want in cases:
        ev = narrative.classify(line)
        ev["body"] = "H"
        got = narrative.stage_of(ev)[1]
        if got != want:
            wrong.append(f"{line[:26]}... -> {got}, wanted {want}")
    assert not wrong, "; ".join(wrong)
    return "ok", "bare->floor, committee->committee, enrolled->governor"


@check("narrative", "an amendment row that states no rejection is not called rejected",
       needs=("narrative",))
def _amend_not_rejected(narrative):
    """A row with no motion the amendment pattern reads was written "was
    rejected" -- 192 rows on 118 bills of 2007-2026, falsely for 150. HB 266
    of 2026 read that 2026-0720s was rejected and then adopted: the first
    row is the Senate announcing it. The rest are words the pattern does not
    take. Every line below is a real docket row."""
    N = narrative
    from datetime import datetime as _dt

    def one(line, body="S"):
        ev = N.classify(line)
        ev["body"] = body
        return N.describe(ev, body) or ""

    def history(bill, lines, session="2026"):
        # A database-era session is read by that era's own vocabulary, the
        # way the real rows are; each row is entered a minute after the one
        # before it, on one day.
        rows = [{"lsr": "", "session": session, "body": b, "desc": d,
                 "created": _dt(int(session), 2, 19, 10, i), "flags": []}
                for i, (b, d) in enumerate(lines)]
        keep = N.TERM
        try:
            N.TERM = N.P.term_of(session)
            return N.build(bill, rows)["narrative"]
        finally:
            N.TERM = keep

    bad = []
    for line, body, want, never in (
            ("Sen. Watters Withdraws Floor Amendment #2018-1018s ; 03/15/2018; SJ 8", "S",
             "was withdrawn", "rejected"),
            ("Committee Amendment #2020-1471s : Sections 1-6 and Sections 9-24, RC 14Y-10N, AA; "
             "06/16/2020; SJ 8", "S", "Part of the committee's amendment (2020-1471s) was adopted "
             "on a roll call 14–10", "rejected"),
            ("Committee Amendment #2020-1471s : Sections 7 and 24, RC 12Y-12N, AF; 06/16/2020; "
             "SJ 8", "S", "was rejected on a roll call 12–12", "adopted"),
            # Alone, a row cannot say the docket holds no vote: that is a
            # claim about the bill's other rows, which only build() reads.
            ("Sen. Rosenwald Floor Amendment # 2025-0752s; 03/06/2025;  SJ 6", "S",
             "proposed a floor amendment (2025-0752s)", "rejected|no vote"),
            ("Sen. Soucy Floor Amendment #2016-1160s , Not Voted On; 03/24/2016; SJ 10", "S",
             "it was not voted on", "rejected"),
            ("Floor Amendment #2014-1812h (Rep. Hoell) MF RC 110-205", "H",
             "was rejected on a roll call 110–205", "adopted"),
            # A calendar's notice of an amendment to come is not a floor
            # amendment offered (HB 1661 of 2022).
            ("Amendment #2022-1475s to HB 1661 will be proposed; SC 16", "S",
             "Notice was given that an amendment (2022-1475s) would be proposed",
             "floor|rejected|no vote")):
        got = one(line, body)
        if (want not in got or any(x in got for x in never.split("|"))
                or "Offered," in got or "Withdraws," in got):
            bad.append(f"{line[:40]}... -> {got!r}")
    got = history("HB266", [
        ("S", "Sen. Birdsell Floor Amendment # 2026-0720s; 02/19/2026;  SJ 4"),
        ("S", "Chair Ruled Sections of Amendment # 2026-0720s Non-Germane, 02/19/2026;  SJ 4"),
        ("S", "Sen. Birdsell Floor Amendment # 2026-0720s, AA, VV; 02/19/2026;  SJ 4")])
    if "rejected" in got or got.count("2026-0720s") != 1:
        bad.append(f"HB 266: {got!r}")
    got = history("SB535", [
        ("S", "Sen. Soucy Floor Amendment #2016-1160s , Not Voted On; 03/24/2016; SJ 10"),
        ("S", "Sen. Soucy Floor Amendment #2016-1160s , AF, VV; 03/24/2016; SJ 10")])
    if "not voted on" in got or "rejected on a voice vote" not in got:
        bad.append(f"SB 535: {got!r}")
    # "THE DOCKET RECORDS NO VOTE ON IT" is a claim about every row of the
    # bill, and was made on six bills whose other rows held the vote: the
    # number spelled another way, or on a row that is not an amendment row.
    # Each history below is the real bill's rows for that amendment.
    for bill, session, lines, want, never in (
            # Decided on rows that begin with the number, and passed with it.
            ("SB318", "2018", [
                ("S", "Sen. Bradley Offered Floor Amendment #2018-1198s ; 03/22/2018; SJ 10"),
                ("S", "Sen. Feltes Moved to divide the Question on 2018-1198s; 03/22/2018; SJ 10"),
                ("S", "2018-1198s All Remaining Sections, and Sec.13, RC 11Y-10N, Adopted; "
                      "03/22/2018; SJ 10"),
                ("S", "Ought to Pass with Amendment 2018-1198s, RC 11Y-10N, MA; OT3rdg; "
                      "03/22/2018; SJ 10")],
             "proposed a floor amendment (2018-1198s)", "no vote|rejected"),
            # "2013-1554h" announced in May, "1554h" rejected in June: told once.
            ("SCR1", "2013", [
                ("H", "Floor Amendment #2013-1554h(NT) (Rep Cushing); HJ41, PG.1410-1412"),
                ("H", "Floor Amendment #1554h(NT) (Rep Cushing): AF VV; HJ52, PG.1709-1711")],
             "(1554h) was rejected on a voice vote", "no vote|2013-1554h"),
            ("HB422", "2014", [
                ("S", "Sen. Boutin Floor Amendment #2014-1550s"),
                ("S", "Sen. Boutin Withdrew Floor Amendment 1550s")],
             "it was later withdrawn", "no vote|rejected"),
            ("SB119", "2025", [
                ("S", "Sen. Rosenwald Floor Amendment # 2025-0752s; 03/06/2025;  SJ 6"),
                ("S", "Chair Ruled Sections of Amendment # 2025-0752s Non-Germane, "
                      "03/06/2025;  SJ 6")],
             "the chair ruled sections of it non-germane", "no vote|rejected"),
            # Where nothing else names it, it is still said (SB 296 of 2014).
            ("SB296", "2014", [
                ("H", "Floor Amendment #2014-1494h (Rep. Baldasaro)")],
             "the docket records no vote on it", "rejected"),
            # A withdrawn amendment is one of the day's run, and the count
            # says so: HB 1 of 2011 read "took up 13" where it took up 16.
            ("HB1", "2011", [
                ("H", "Floor Amendment #2011-1261h (Rep Foose) Failed, RC 106-251; HJ 35, PG.1225-1227"),
                ("H", "Floor Amendment #2011-1306h (Rep Emerson), Withdrawn; HJ 35, PG.1227-1230"),
                ("H", "Floor Amendment #2011-1321h (Rep Hatch) Failed, RC 107-254; HJ 35, PG.1230-1232"),
                ("H", "Floor Amendment #2011-1322h (Rep Hatch) Failed, RC 106-249; HJ 35, PG.1232-1234")],
             "took up 4 floor amendments", "took up 3|A floor amendment (2011-1306h)"),
            # The database era reads "Div." as a division and leaves the
            # tally on the row: HB 1487 of 2012.
            ("HB1487", "2012", [
                ("S", "Sen. Bradley Floor Amendment #2012-1903s, Div. 16Y-8N, AA; SJ 12, Pg.439")],
             "adopted on a division vote 16–8", "rejected")):
        got = history(bill, lines, session)
        if want not in got or any(x in got for x in never.split("|")):
            bad.append(f"{bill} of {session}: {got!r}")
    assert not bad, "; ".join(bad)
    return "ok", ("an announcement gives way to the row that decides it, however it spells "
                  "the number; no vote is claimed while another row names it; withdrawn, not "
                  "voted on, part of an amendment and codes out of order read as they say")


@check("narrative", "veto and enactment sentences render", needs=("narrative",))
def _veto_sentences(narrative):
    out = []
    for line, body in ((DOCKET_LINES[0][1], "H"), (DOCKET_LINES[1][1], "S"),
                       (DOCKET_LINES[2][1], "H"), (DOCKET_LINES[4][1], "H")):
        s = narrative.describe(narrative.classify(line), body)
        assert s, f"no sentence for {line[:40]}"
        out.append(s)
    assert "sustained" in out[0], "House veto line lost its outcome"
    assert "override the governor" in out[1], "Senate override line lost its outcome"
    assert "without the governor" in out[2], "unsigned law line lost its meaning"
    return "ok", out[1][:66] + "..."


@check("narrative", "motion movers expand, but only when unambiguous",
       needs=("narrative",))
def _movers(narrative):
    roster = [{"name": "Germana, Nicholas", "chamber": "H"},
              {"name": "Osborne, Jason", "chamber": "H"},
              {"name": "Osborne, Marjorie", "chamber": "H"},
              {"name": "Altschiller, Debra", "chamber": "S"}]
    tmp = Path(tempfile.mkdtemp()) / "roster.json"
    tmp.write_text(json.dumps(roster), encoding="utf-8")
    keep = narrative.MEMBERS
    try:
        narrative.MEMBERS = narrative.load_members(tmp)
        got = [narrative.expand_mover(x) for x in
               ("Rep. N. Germana", "Sen. D. Altschiller", "Rep. Osborne")]
        assert got[0] == "Rep. Nicholas Germana", got[0]
        assert got[1] == "Sen. Debra Altschiller", got[1]
        assert got[2] == "Rep. Osborne", f"two Osbornes, picked one: {got[2]}"
        narrative.MEMBERS = {}
        assert narrative.expand_mover("Rep. N. Germana") == "Rep. N. Germana"
    finally:
        narrative.MEMBERS = keep
        shutil.rmtree(tmp.parent, ignore_errors=True)
    return "ok", "expanded 2, left the shared surname alone, no roster is a no-op"


# =============================================================== code: status ==

def _narr(lines, body="H"):
    return {"events": [{"raw": x, "type": "other", "date": "2026-08-19",
                        "body": body} for x in lines]}


@check("status", "a sustained veto beats an overridden one", needs=("build_site_v2",))
def _veto_status(build_site_v2):
    B = build_site_v2
    # The chambers, as the real docket has them: the Senate overrode and the
    # House sustained, on the same day. An override needs both.
    both = _narr(["Vetoed by Governor 07/15/2026",
                  "Veto Sustained 08/19/2026: RC 165-140 Lacking Necessary "
                  "Two-Thirds Vote"])
    both["events"] += _narr(["Notwithstanding the Governor's Veto, Shall SB 434 "
                             "Become Law: RC 16Y-8N, Veto Overridden by "
                             "necessary two-thirds vote; 08/19/2026"],
                            body="S")["events"]
    # And one chamber reconsidering its own vote: sustained, then overridden.
    same = _narr(["Vetoed By Governor 07/13/2011",
                  "Shall HB 542 Become Law: Veto Sustained, RC 244-130",
                  "Veto Overridden: RC 255-112 By Required Two-Thirds Vote"])
    assert B.classify(same, [])[0] == "law", "a chamber may reconsider"
    assert B.docket_outcome(same)[0] == "law", "a chamber may reconsider"
    kind, label = B.classify(both, [])
    assert kind == "veto", f"SB 434 shape came out as {kind}/{label}"
    step = B.next_step(both, {})
    assert "dead" in step.lower(), step
    return "ok", f"{label} / {step}"


@check("status", "a stated override in one chamber and sustained veto in the other is a veto",
       needs=("build_site_v2",))
def _veto_split_stated(build_site_v2):
    """The same rule as the check above, for the status fields rather than
    the docket. HB 503 of 2003: VETOED BY GOVERNOR, House VETO OVERRIDDEN,
    Senate VETO SUSTAINED -- published as "Veto overridden, became law"
    until 11 September, with ten others like it."""
    B = build_site_v2
    for house, senate in (("VETO OVERRIDDEN", "VETO SUSTAINED"),
                          ("VETO SUSTAINED", "VETO OVERRIDDEN")):
        got = B.classify_stated({"gen_status": "VETOED BY GOVERNOR",
                                 "house_status": house,
                                 "senate_status": senate}, "HB")
        assert got and got[0] == "veto", (
            f"House {house}, Senate {senate} came out as {got}")
    both = B.classify_stated({"gen_status": "VETOED BY GOVERNOR",
                              "house_status": "VETO OVERRIDDEN",
                              "senate_status": "VETO OVERRIDDEN"}, "HB")
    assert both and both[0] == "law", f"overridden in both came out as {both}"
    return "ok", "sustained in either chamber is a veto; overridden in both is law"


@check("status", "a bill with no narrated docket is read from its signature line and its fields' own stage",
       needs=("build_site_v2",))
def _unnarrated_status(build_site_v2):
    """Two rules for the twelve terms whose dockets are not narrated.

    HB 1075 of 1998 was signed (\"SIGNED BY GOVERNOR 10/01/98 ... CHAP.0389\")
    and read "In committee", its fields stopping at CONFERENCE REPORT
    ADOPTED: the signature line extract_chapters keeps now settles it. And
    495 bills read "In committee" or "In progress" -- this site's guess --
    over fields naming a stage; the field's stage replaces the guess, but
    never a docket's own outcome."""
    B = build_site_v2
    conf = {"gen_status": "SENATE", "house_status": "CONFERENCE REPORT ADOPTED",
            "senate_status": "CONFERENCE REPORT ADOPTED"}
    d = B.bill_disposition({}, "HB1075", conf, None, [], "1997-1998",
                           "2025-2026", law_line="SIGNED BY GOVERNOR  10/01/98 "
                           "EFF: 10/01/98* CHAP.0389")
    assert (d.kind, d.status) == ("law", "Signed into law"), d
    d = B.bill_disposition({}, "HB42", conf, None, [], "1989-1990", "2025-2026")
    assert d.status == "Conference committee report adopted", d.status
    filed = {"gen_status": "HOUSE", "house_status": "REPORT FILED",
             "senate_status": ""}
    d = B.bill_disposition({}, "HB190", filed, None, [], "1989-1990", "2025-2026")
    assert (d.kind, d.status) == ("done", "Committee report filed"), d
    killed = _narr(["Inexpedient to Legislate: MA VV 03/06/2024"])
    killed["events"][0].update(type="floor", motion="MA",
                               action="Inexpedient to Legislate")
    d = B.bill_disposition({}, "HB1", filed, killed, [], "2023-2024", "2025-2026")
    assert d.status == "Killed", f"a docket's kill gave way to a field: {d.status}"
    # A veto in a closed term: the docket's failed override where there is
    # one, and never "awaiting an override vote" twenty-eight years on.
    vetoed = {"gen_status": "VETOED BY GOVERNOR", "house_status": "",
              "senate_status": ""}
    d = B.bill_disposition({}, "HB149", vetoed, None, [], "1997-1998",
                           "2025-2026", override_failed="OVERRIDE GOV VETO, "
                           "ML RC(17-299)")
    assert d.status == "Vetoed, override failed", d.status
    d = B.bill_disposition({}, "HB1407", vetoed, None, [], "1991-1992",
                           "2025-2026")
    assert d.status == "Vetoed", d.status
    d = B.bill_disposition({}, "HB9", vetoed, None, [], "2025-2026",
                           "2025-2026")
    assert d.status == "Vetoed, awaiting an override vote", d.status
    return "ok", ("signed from the line; the field's stage, never over the "
                  "docket; a closed term's veto awaits nothing")


@check("status", "law without a signature reads as law", needs=("build_site_v2",))
def _unsigned_status(build_site_v2):
    n = _narr(["Enacted in accordance with Article 44 PartII of the N.H. "
               "Constitution without the signature of the governor. Chapter 343"])
    kind, label = build_site_v2.classify(n, [])
    assert kind == "law", f"came out as {kind}/{label}"
    return "ok", f"{label} / {build_site_v2.next_step(n, {})}"


@check("status", "the status box never claims another kind of status than the chip",
       needs=("build_site_v2",))
def _next_step_agrees(build_site_v2):
    """next_step() reads the last docket event, and that is often not the one
    that decided the bill. HB 691 of 2025's last row is the House killing it,
    190-156 -- a floor row, so the box read "Pending action in the other
    chamber" under "Killed"; HB 675 of 2026's is a failed motion to
    reconsider its kill; HR 24 of 2000's is a rules suspension, read as
    "Adopted" under "In committee"; HB 542 of 2011, overridden and Chapter
    271, read "The override failed". 130 records of 2025-2026 and two of
    closed terms. The General Court's own field wording, and a line that
    says the same thing as the chip in other words, are left as they are."""
    B = build_site_v2
    now = "2025-2026"
    hb691 = _nar(_ev("H", "Committee Report: Inexpedient to Legislate 02/12/2025 (Vote 14-1; CC)",
                     "report"),
                 _ev("H", "Inexpedient to Legislate: MA RC 190-156 03/06/2025", "floor", "MA",
                     "Inexpedient to Legislate"))
    step = B.next_step(hb691, {}, "HB")
    assert step.startswith("Pending"), (
        f"HB 691's last row no longer reads as pending ({step!r}), so this "
        "check no longer exercises the case it was written for")
    bad = []
    for step, status, term, kind, want in (
            (step, "Killed", now, "done", "Killed"),
            ("In progress", "In a committee of conference", now, "done",
             "In a committee of conference"),
            ("Adopted. A resolution of one chamber goes no further", "In committee",
             "1999-2000", "done", "In committee"),
            ("Vetoed. The override failed and the bill is dead",
             "Veto overridden, became law", "2011-2012", "law", "Veto overridden, became law"),
            # Left alone: the same claim in other words, the fields, a live bill.
            ("Vetoed. The override failed and the bill is dead", "Vetoed, override failed",
             now, "veto", None),
            ("Became law without the governor's signature", "Became law unsigned", now, "law", None),
            ("Died when the session ended", "Died on the table", now, "done", None),
            ("House: INEXPEDIENT TO LEGISLATE", "Killed", now, "done", None),
            ("Pending action in the other chamber", "Passed one chamber", now, "active", None)):
        got = B.settled_step(step, status, term, now, kind)
        if got != (want or step):
            bad.append(f"{step[:30]!r} under {status!r}: {got!r}")
    assert not bad, "; ".join(bad)
    return "ok", "a pending, adopted or vetoed line gives way to a chip of another kind"


def _ev(body, raw, type_="other", motion=None, action=None, date="2026-01-01"):
    return {"body": body, "raw": raw, "type": type_, "motion": motion,
            "action": action, "cancelled": False, "date": date}


def _nar(*evs, hands=()):
    return {"events": list(evs), "stages": [{"hand": h} for h in hands]}


@check("status", "what the two chambers did with each other's version is read from the docket",
       needs=("build_site_v2",))
def _between_chambers(build_site_v2):
    """Every line below is a real docket row, quoted from Docket.txt,
    Docket_2023-2024.txt, Docket_2021-2022.txt, Docket_db_* or the narrated
    record built from them.

    The status fields name one chamber's last stage and stop: CACR 13 of
    2026 read "Passed one chamber" beside its own "Senate: PASSED/ADOPTED";
    HB 1215 of 2024 read "Conference committee report adopted" over the
    House voting that report down 102-261; SB 34 of 2026 read "Passed one
    chamber" after the Senate refused to concur; HB 589 of 2002 read
    "Retained in committee" after passing both chambers. This fails on a
    return to any of them, on a reconsidered report read as rejected, and on
    a CACR said to be going to an election that has passed.
    """
    B = build_site_v2
    bad = []

    def want(label, got, what):
        if got != label:
            bad.append(f"{what}: wanted {label!r}, got {got!r}")

    # CACR 13 of 2026: both chambers by three fifths, and its own text names
    # the election -- future tense before it, past tense after.
    st = {"gen_status": "SENATE", "senate_status": "PASSED/ADOPTED", "body": "H"}
    n = _nar(_ev("H", "Introduced 01/07/2026 and referred to Judiciary", "introduced"),
             _ev("H", "Ought to Pass: MA DV 325-15 By Necessary Three-Fifths Vote 02/05/2026",
                 "floor", "MA", "Ought to Pass"),
             _ev("S", "Ought to Pass, RC 23Y-1N, MA, by Necessary 3/5; OT3rdg; 03/26/2026"))
    text = ("submitted to the qualified voters of the state at the state general "
            "election to be held in November, 2026.")
    d = B.bill_disposition({}, "CACR13", st, n, [], "2025-2026", "2025-2026",
                           term_over=True, text=text, today=B._date(2026, 9, 23))
    want("Passed both chambers, goes to the voters in November 2026", d.status, "CACR13 before the election")
    want("adopted", d.kind, "CACR13's kind")
    d = B.bill_disposition({}, "CACR13", st, n, [], "2025-2026", "2025-2026",
                           term_over=True, text=text, today=B._date(2026, 11, 4))
    want("Passed both chambers, went to the voters in November 2026", d.status, "CACR13 after the election")
    d = B.bill_disposition({}, "CACR13", st, n, [], "2025-2026", "2027-2028")
    want("Passed both chambers, went to the voters", d.status, "a closed term's CACR")
    # The voters' own answer, where the docket records it.
    for raw, label in (("Amendment Failed Referendum (271,091 - 205,589); 2005 Red Book, p.___",
                        "Passed both chambers, not ratified by the voters"),
                       ("AMENDMENT ADOPTED BY 2/3 REF(199,229-26,336); 1991 RED BOOK,P294",
                        "Passed both chambers, ratified by the voters")):
        n2 = _nar(*n["events"], _ev("H", raw))
        d = B.bill_disposition({}, "CACR5", st, n2, [], "2003-2004", "2025-2026")
        want(label, d.status, raw[:30])
    # HCR 10 of 2024: gen_status PASSED and a House-only docket -- not both.
    st = {"gen_status": "PASSED", "house_status": "PASSED/ADOPTED", "senate_status": "", "body": "H"}
    n = _nar(_ev("H", "Ought to Pass : MA VV 02/01/2024", "floor", "MA", "Ought to Pass"))
    want("Passed one chamber", B.bill_disposition({}, "HCR10", st, n, [], "2023-2024",
                                                  "2025-2026").status, "HCR10 2024")
    # HCR 6 of 1990: the Senate's adoption is in the docket, not the fields.
    st = {"gen_status": "", "house_status": "PASSED/ADOPTED", "senate_status": ""}
    n = _nar(_ev("H", "REPS PALUMBO & CHAMBERS SUSP RULES TO CONSIDER, MA 2/3VV, ADOPTED HJ24, P399",
                 "floor", "MA", "Adopted"),
             _ev("S", "INTRODUCED AND ADOPTED", "floor", "MA"))
    d = B.bill_disposition({}, "HCR6", st, n, [], "1989-1990", "2025-2026")
    want("Adopted by both chambers", d.status, "HCR6 1990")
    # HB 1215 of 2024: the Senate adopted the report and the House voted it down.
    st = {"gen_status": "SENATE", "house_status": "CONFERENCE REPORT FAILED",
          "senate_status": "CONFERENCE REPORT ADOPTED"}
    n = _nar(_ev("H", "Ought to Pass with Amendment 2024-1080h: MA VV 03/28/2024", "floor", "MA",
                 "Ought to Pass with Amendment"),
             _ev("H", "House Concurs with Senate Amendment 2024-1961s (Rep. Alexander Jr.): MF RC 172-180 05/30/2024",
                 "floor", "MF"),
             _ev("H", "House Non-Concurs with Senate Amendment 2024-1961s and Requests CofC (Rep. Alexander Jr.): MA VV 05/30/2024",
                 "floor", "MA"),
             _ev("S", "Conference Committee Report #2024-2273c , Adopted, VV; 06/13/2024"),
             _ev("H", "Conference Committee Report 2024-2273c: Failed, RC 102-261 06/13/2024"))
    d = B.bill_disposition({}, "HB1215", st, n, [], "2023-2024", "2025-2026")
    want(B.CONF_REJECTED, d.status, "HB1215 2024")
    if not d.between:
        bad.append("HB1215 2024: decided by the docket but not marked so for status_source")
    # The older dockets' words for a report voted down, and a new conference
    # the other chamber refused (HB 381 of 2006, HB 252 of 2000, HB 1211 of 1992).
    for raws in (["Committee of Conference Report {2101}, Division 14Y-9N, Adopted",
                  "Conf Comm Report lost RC(154-175)"],
                 ["Conf Comm Report, Sen Trombly, MA, VV",
                  "Conf Comm Report Fails DIV(76-210); HJ77, p2079"],
                 ["CONF COMM REPORT ADOPTED VV; SJ21,P618-619",
                  "CONF COMM REPORT LOST RC(117-206); HOUSE DISCHARGE CONF COMM, REQ NEW CONF COMM, REP GROSS MA VV; HJ82,P2121-2124",
                  "SEN REFUSED TO ACCEDE TO REQ FOR NEW CONF COMM, SEN W. KING MA VV; SJ21,P670"]):
        got = B.between_chambers(_nar(*[_ev("H" if i % 2 else "S", r) for i, r in enumerate(raws)]),
                                 "Conference committee report adopted")
        want(("done", B.CONF_REJECTED), got, raws[-1][:34])
    # SB 14 of 2025: failed 183-186, reconsidered, adopted 185-182 -- not rejected.
    n = _nar(_ev("H", "Conference Committee Report 2025-2850c: Failed, RC 183-186 06/26/2025"),
             _ev("H", "Reconsider Adopt CofC Report (Rep. Litchfield): MA RC 184-182 06/26/2025"),
             _ev("H", "Conference Committee Report 2025-2850c: Adopted, RC 185-182 06/26/2025"))
    got = B.between_chambers(n, "In a committee of conference")
    if got and got[1] == B.CONF_REJECTED:
        bad.append("SB14 2025: a report adopted on reconsideration read as rejected")
    # SB 135 of 2013: a failed motion to RECONSIDER an adopted report, on a
    # bill that went to the governor, is not the report failing. In the
    # docket's own order (10:53:04, then 10:53:40) the reconsideration is the
    # House's last word, so only the skip keeps it from reading as rejected;
    # same-day rows are not reliably in order, so both orders are tried.
    adopt = _ev("H", "Conference Committee Report #2089c Adopted, VV; HJ52, PG.1675")
    recon = _ev("H", "Reconsideration, Conference Committee Report #2089c (Rep Lambert): MF RC 108-247; HJ52, PG.1678-1680", "floor", "MF")
    senate = _ev("S", "Conference Committee Report 2089c; Adopted, VV")
    for order in ((adopt, recon, senate), (recon, adopt, senate)):
        got = B.between_chambers(_nar(*order), "Passed, awaiting the governor")
        if got:
            bad.append(f"SB135 2013: a failed reconsideration moved an enrolled bill to {got}")
    # The report's own clause decides, not the row: HB 170 of 2001's failed
    # motion to reconsider follows the report on the same row, and HB 50 of
    # 1997's failed motion to table comes before it.
    for raws in (("Conference Committee Report, , RC 15Y-9N, Adopted; SJ 19, Pg.592-623",
                  "Conf Comm Report Adopted RC(190-181);  Rep Herman moved to Reconsider, ML RC(177-192);"),
                 ("CONF COMM REPORT ADOPTED RC(22-2); SJ23(I),P5527-532",
                  "REP K SMITH MOVED LOT, ML RC(112-252); CONF COMM REPORT ADOPTED")):
        got = B.between_chambers(_nar(_ev("S", raws[0]), _ev("H", raws[1])),
                                 "Conference committee report adopted")
        if got:
            bad.append(f"{raws[1][:30]}: another motion's ML read as the report failing ({got})")
    # SB 34 of 2026: the House passed it amended, the Senate refused to concur.
    st = {"house_status": "PASSED/ADOPTED WITH AMENDMENT", "senate_status": None}
    n = _nar(_ev("S", "Ought to Pass: RC 16Y-8N, MA; OT3rdg; 03/06/2025"),
             _ev("H", "Ought to Pass with Amendment 2025-3056h: MA RC 186-155 01/07/2026", "floor",
                 "MA", "Ought to Pass with Amendment"),
             _ev("S", "Sen. Ward Moved Nonconcur with the House Amendment, MA, VV; 02/05/2026",
                 "floor", "MA"))
    d = B.bill_disposition({}, "SB34", st, n, [], "2025-2026", "2025-2026", term_over=True)
    want("One chamber did not concur", d.status, "SB34 2026")
    # HB 549 of 1991: both chambers' fields say PASSED/ADOPTED, the Senate's
    # WITH AMENDMENT, and the House never took the amendment up -- not
    # "Passed one chamber". A House resolution the docket shows "Introduced
    # and Adopted" (HR 13 of 2007) is not "In committee".
    st = {"gen_status": "SENATE", "house_status": "PASSED/ADOPTED WITH AMENDMENT",
          "senate_status": "PASSED/ADOPTED WITH AMENDMENT"}
    n = _nar(_ev("H", "APPROP AM, AA VV; PASSED WITH AM VV; HJ65,P1476 + 1480", "floor", "MA",
                 "Passed with Am"),
             _ev("S", "FL AM (NEW TITLE), AA VV; SEN W. KING FL AM (NEW TITLE), AA VV; PASSED WITH "
                      "AM VV; SJ34,P696-697 + 699", "floor", "MA", "Passed with Am"))
    want("Died when the session ended", B.bill_disposition({}, "HB549", st, n, [], "1991-1992",
                                                           "2025-2026").status, "HB549 1991")
    want("Adopted by the House", B.bill_disposition(
        {}, "HR13", {"gen_status": "HOUSE", "house_status": "", "senate_status": ""},
        _nar(_ev("H", "Introduced and Adopted")), [], "2007-2008", "2025-2026").status, "HR13 2007")
    # HB 1432 of 2022: the conference asked for was refused, so none sat.
    n = _nar(_ev("H", "House Non-Concurs with Senate Amendment 2022-1837s and Requests CofC (Reps. McConkey, Milz, B. Boyd, Fedolfi): MA VV 05/05/2022", "floor", "MA"),
             _ev("S", "Sen. Birdsell Refused to Accede to House Request for Committee of Conference, MA, VV; 05/12/2022", "floor", "MA"))
    want(("active", "One chamber did not concur; a committee of conference was asked for"),
         B.between_chambers(n, "In a committee of conference"), "HB1432 2022")
    # HB 589 of 2002: retained, then passed both chambers and went to conference.
    n = _nar(_ev("H", "Retained in Committee", "retained"),
             _ev("H", "Comm Am{2307}, AA VV; Passed with Am VV", "floor", "MA", "Ought to Pass with Amendment"),
             _ev("S", "Ought to Pass with Amendment, MA, VV", "floor", "MA", "Ought to Pass with Amendment"),
             _ev("H", "House Nonconc with Sen Am req Conf Comm, Rep Gilman MA VV", "floor", "MA"),
             _ev("H", "(Conf Comm Report Not Signed)"))
    d = B.bill_disposition({}, "HB589", {}, n, [], "2001-2002", "2025-2026")
    if d.status == "Retained in committee" or B.classify(n, [], "HB")[1] == "Retained in committee":
        bad.append("HB589 2002: still 'Retained in committee' after passing both chambers")
    # 2020: laid on the table in the Senate, killed at adjournment by Rule 3-23.
    st = {"senate_status": "LAID ON TABLE"}
    n = _nar(_ev("S", "Vacated from Committee and Laid on Table, MA, VV; 06/16/2020", "floor", "MA"),
             _ev("S", "Inexpedient to Legislate, Senate Rule 3-23, Adjournment 09/16/2020"))
    want("Died on the table", B.bill_disposition({}, "CACR20", st, n, [], "2019-2020",
                                                 "2025-2026").status, "CACR20 2020")
    # The rails: no governor on a resolution, both chambers passed on one
    # both adopted, and two stops for a special session's House resolution.
    rail = B.passage([{"hand": "H:floor"}, {"hand": "S:floor"}, {"hand": "G:governor"}],
                     "adopted", "Passed both chambers, went to the voters", "CACR5")
    want("Hpp--", rail, "CACR5 2004's rail")
    want("Hpp", B.passage([{"hand": "H:floor"}], "adopted", "Adopted by the House", "SSHR1"),
         "SSHR1 2008's rail")
    # Both chambers decided, and the docket's first row is the second
    # chamber's: the bill's number says where it started. HB 1650 of 2022's
    # House rows were entered after the Senate's; HB 652 of 2011's Senate
    # introduction is dated before the House passed it.
    want("Hpppp", B.passage([{"hand": "S:floor"}, {"hand": "G:governor"}], "law",
                            "Signed into law", "HB1650", {"H", "S"}, ["S", "H"]),
         "HB1650 2022's rail")
    want("Hpx-x", B.passage([{"hand": "S:committee"}, {"hand": "H:floor"}, {"hand": "S:floor"}],
                            "done", "Killed", "HB652", {"H"}, ["H", "S"]), "HB652 2011's rail")
    assert not bad, "; ".join(bad)
    return "ok", ("both chambers adopted, a report voted down, a refusal to concur, "
                  "a retention moved past, the voters' answer, each from the docket")


@check("status", "conferees who could not agree end the bill, and nothing says their report was adopted",
       needs=("build_site_v2",))
def _conferees_could_not_agree(build_site_v2):
    """69 bills of 1989-2010 read "Conference committee report adopted", the
    status fields' CONFERENCE REPORT ADOPTED, where every one's docket says
    the conferees were unable to agree and the bill died: HB 42 of 1989, "CONF
    COMM REPORT ADOPTED VV, UNABLE TO AGREE"; HB 431 of 2010, whose "Unable to
    Reach Agreement" is on the row that files the report and not the one that
    adopts it. The rows below are theirs. A report adopted where the
    conferees agreed keeps its label, and so does one a new conference
    replaced (HB 1210 of 2002, Chapter 230); one the other chamber refused to
    replace does not (SB 69 of 2001)."""
    B = build_site_v2
    bad = []
    conf = {"gen_status": "SENATE", "house_status": "CONFERENCE REPORT ADOPTED",
            "senate_status": "CONFERENCE REPORT ADOPTED"}
    otpa = "Ought to Pass with Amendment"
    ask = _ev("H", "HOUSE NONCONCUR WITH SEN AM, REQ CONF COMM, REP WARD MA VV", "floor", "MA",
              "Nonconcur", date="1989-05-12")
    hb42 = _nar(_ev("H", "PASSED/ADOPTED WITH AM; HJ21, P337-338 + 347", "floor", "MA", otpa,
                    date="1989-02-09"),
                _ev("S", "PASSED/ADOPTED WITH AM", "floor", "MA", otpa, date="1989-05-09"),
                ask, _ev("S", "SENATE ACCEDED TO REQ FOR CONF COMM", date="1989-05-16"),
                _ev("S", "CONFEREES UNABLE TO AGREE", date="1989-05-23"),
                _ev("H", "CONF COMM REPORT ADOPTED VV, UNABLE TO AGREE; HJ93, P2789", "floor",
                    "MA", "Conference Committee Report", date="1989-05-23"))
    hb431 = _nar(_ev("H", "Ought to Pass: MA DIV 251-92", "floor", "MA", "Ought to Pass",
                     date="2010-03-24"),
                 _ev("S", "Ought to Pass with Amendment 2063s, MA, VV; OT3rdg", "floor", "MA",
                     "Ought to Pass with Amendment 2063s", date="2010-05-13"),
                 _ev("H", "House Non-Concurs with Senate AM and Requests Comm of Conf (Rep Hess): MA VV",
                     "floor", "MA", "House Non-Concurs with Senate AM and Requests Comm of Conf "
                     "(Rep Hess)", date="2010-05-19"),
                 _ev("H", "Conference Committee Report 2246; Unable to Reach Agreement, Filed",
                     date="2010-05-27"),
                 _ev("S", "Conference Committee Report 2246; Adopted, VV", date="2010-06-02"),
                 _ev("H", "Conference Committee Report #2246 Adopted, VV", date="2010-06-02"))
    for bid, term, n in (("HB42", "1989-1990", hb42), ("HB431", "2009-2010", hb431)):
        d = B.bill_disposition({}, bid, conf, n, [], term, "2025-2026")
        if (d.kind, d.status) != ("done", B.CONF_UNABLE) or not d.between:
            bad.append(f"{bid} of {term}: {(d.kind, d.status, d.between)}")
            continue
        end = B.closing_stage(d.status, n) or {}
        if not end.get("text") or "adopted" in end["text"].lower():
            bad.append(f"{bid}: How it ended reads {end.get('text')!r}")
        _intro, steps = B.journey(n, bid, [], "", "", term)
        said = [s["text"] for s in steps if s["act"] == "conf_adopted"]
        if not said or any("could not agree" not in t for t in said):
            bad.append(f"{bid}: How it got here reads {said!r}")
        # Never "...could not agree on a voice vote": it reads as though the
        # voice vote were what they could not agree on.
        if any(t.rstrip().endswith("could not agree on a voice vote") for t in said):
            bad.append(f"{bid}: How it got here reads {said!r}, which puts the vote "
                       "after 'could not agree'")
        rail = B.passage(n.get("stages"), d.kind, d.status, bid, {"H", "S"}, ["H", "S"])
        why = B.journey_disagrees(steps, d.kind, d.status, rail, bid)
        if why:
            bad.append(f"{bid}: the journey disagrees with its status: {why}")
    # Agreed, and a report replaced by a new conference: the label stands.
    agreed = _nar(ask, _ev("S", "Conference Committee Report #2089c Adopted, VV; SJ 19"),
                  _ev("H", "Conference Committee Report #2089c Adopted, VV; HJ52, PG.1675"))
    renewed = _nar(ask, _ev("S", "Conference Committee Report [Not Signed]"),
                   _ev("H", "CONF COMM REPORT (UNABLE TO AGREE) FILED"),
                   _ev("H", "Rep Goulet Susp Rules for New Conf Comm, MA 2/3DIV(256-44); House Acceded to req"),
                   _ev("H", "New Conf Comm Report{3763} Adopted VV; HJ40, p1487"))
    for what, n in (("an agreed report", agreed), ("a report a new conference replaced", renewed)):
        d = B.bill_disposition({}, "HB1210", conf, n, [], "2001-2002", "2025-2026")
        if d.status != "Conference committee report adopted":
            bad.append(f"{what}: {d.status!r}")
    refused = [_ev("S", "Conf Comm Report (UNABLE TO AGREE) Filed"),
               _ev("S", "Sen. Pignatelli Motion to Request New Committee of Conference MA, VV"),
               _ev("H", "House Refused to Accede to req for New Conf Comm, Rep Mock MA VV; HJ61, p1797")]
    if not B.conferees_disagreed(refused):
        bad.append("SB69 of 2001: a new conference the House refused undid the report of no agreement")
    assert not bad, "; ".join(bad)
    return "ok", (f"{B.CONF_UNABLE!r}, with a closing paragraph and a journey that say so; "
                  "an agreed or replaced report keeps its label")


@check("status", "a kill the chamber reconsidered and then passed the bill over is not a kill",
       needs=("build_site_v2",))
def _reconsidered_kill(build_site_v2):
    """HB 323 of 2005 read "Killed". The House adopted Inexpedient to
    Legislate on 23 March 2005, 164-153; on 30 March it reconsidered, 153-150,
    voted the kill down and passed the bill, which the Senate passed and a
    committee of conference never signed a report on. classify() read
    "inexpedient to legislate" anywhere among the motions carried, so the
    kill the House had undone was the answer (approved to fix, 25 September).

    It still reads a kill that stood: HB 1267 of 2012, where a SPECIAL ORDER
    for a reconsideration carried and the reconsideration itself then failed;
    and HB 666 of 1997, reconsidered and killed again in a row the parser reads
    in two halves. Every row below is the bill's own, from its docket.
    """
    B = build_site_v2
    hb323 = _nar(
        _ev("H", "ITL MA RC(164-153)", "floor", "MA", "Inexpedient to Legislate",
            date="2005-03-23"),
        _ev("H", "Rep Norelli moved to Reconsider, MA RC(153-150); ITL ML DIV(149-151); "
                 "Rep Kurk Fl Am{0867}, AA", "floor", "MA", "Reconsider", date="2005-03-30"),
        _ev("H", "DIV(182-116); Passed with Am VV", "floor", "MA",
            "Ought to Pass with Amendment", date="2005-03-30"))
    hb1267 = _nar(
        _ev("H", "Inexpedient to Legislate: MA VV", "floor", "MA", "Inexpedient to Legislate",
            date="2012-03-15"),
        _ev("H", "Special Order (Reconsideration Motion) to Next Session Day (Rep Jasper): MA VV",
            "floor", "MA",
            "Special Order (Reconsideration Motion) to Next Session Day (Rep Jasper)",
            date="2012-03-21"),
        _ev("H", "Reconsideration (Rep DeLemus): MF DIV 103-233", "floor", "MF",
            "Reconsideration (Rep DeLemus)", date="2012-03-28"))
    hb666 = _nar(
        _ev("H", "ITL REPORT ADOPTED VV; HJ33,P798", "floor", "MA", "Inexpedient to Legislate",
            date="1997-03-05"),
        _ev("H", "REP GIBBONS MOVED TO RECONSIDER, MA DIV(213-116); ITL REPORT", "floor", "MA",
            "Reconsider", date="1997-03-05"),
        _ev("H", "ADOPTED RC(233-114); HJ33,P798-800", "floor", "MA", "Adopt",
            date="1997-03-05"))
    got = {bid: B.classify(n, [], "HB") for bid, n in
           (("HB323", hb323), ("HB1267", hb1267), ("HB666", hb666))}
    bad = []
    if got["HB323"] == ("done", "Killed"):
        bad.append("HB 323 of 2005 is 'Killed' by a kill the House reconsidered and passed it over")
    for bid in ("HB1267", "HB666"):
        if got[bid] != ("done", "Killed"):
            bad.append(f"{bid}'s kill stood and it reads {got[bid]}")
    assert not bad, "; ".join(bad)
    return "ok", ("HB 323 of 2005 is not killed by the kill it was reconsidered out of; "
                  "HB 1267 of 2012 and HB 666 of 1997, whose kills stood, are")


@check("status", "conferees who never signed a report end the bill too, and a report signed late does not",
       needs=("build_site_v2",))
def _conferees_never_signed(build_site_v2):
    """Until 25 September 193 bills of 1989-2026, 24 of them this term, read
    "In a committee of conference", "One chamber did not concur; a committee
    of conference was asked for" or "Died when the session ended" where the
    docket says their last conference never agreed: HB 1323 of 2026,
    "Conference Committee Report; Not Signed Off" under fields that stop at
    CONFERENCE COMMITTEE; HB 243 of 2025, the Senate's "Not Signed Off" and
    the House's "Conference Committee Report: Not Filed" under DIED, SESSION
    ENDED; SB 460 of 2026, "Not Filed" alone; HB 291 of 2021 under
    NONCONCURRED REQUEST CONFERENCE; SB 65 of 1989, "DIED IN COMMITTEE OF
    CONFERENCE". Each reads CONF_UNABLE, finished rather than stale, with a
    closing paragraph that says what the docket says and no line of its
    journey rewritten, since no chamber adopted a report. Kept as they are:
    HB 1091 of 2026, whose conferees signed late and whose report the Senate
    adopted before the House refused to take it up, 180-156; HB 1410 of
    2002, whose Senate refused to allow a report after the deadline; HB 723
    of 1997, whose report of no agreement was followed by a new conference
    that never reported. The rows below are theirs."""
    B = build_site_v2
    bad = []
    ev = _ev
    hb1323 = _nar(
        ev("H", "Ought to Pass: MA RC 197-157 02/12/2026", "floor", "MA", "Ought to Pass",
           date="2026-02-12"),
        ev("S", "Ought to Pass with Amendments #2026-1849s and #2026-1982s and #2026-1981s, MA, VV; "
                "OT3rdg; 05/14/2026", "floor", "MA",
           "Ought to Pass with Amendments #2026-1849s and #2026-1982s and #2026-1981s",
           date="2026-05-14"),
        ev("H", "House Non-Concurs with Senate Amendment 2026-1339s 2026-1849s 2026-1982s and "
                "2026-1981s and Requests CofC (Rep. DeSimone): MA VV 05/14/2026", "floor", "MA",
           "House Non-Concurs with Senate Amendment 2026-1339s 2026-1849s 2026-1982s and "
           "2026-1981s and Requests CofC", date="2026-05-14"),
        ev("S", "Sen. Abbas Accedes to House Request for Committee of Conference, MA, VV; 05/21/2026",
           "floor", "MA", "Accedes to House Request for Committee of Conference", date="2026-05-21"),
        ev("H", "Conference Committee Meeting: 05/26/2026 01:00 pm GP 232", "conference_meeting",
           date="2026-05-26"),
        ev("S", "Conference Committee Report; Not Signed Off", date="2026-06-02"))
    hb243 = _nar(
        ev("H", "Ought to Pass: MA VV 02/20/2025", "floor", "MA", "Ought to Pass", date="2025-02-20"),
        ev("S", "Ought to Pass with Amendments #2025-2049s, #2025-2487S, #2025-2665s, and "
                "#2025-2710s, MA, VV; OT3rdg; 06/05/2025", "floor", "MA",
           "Ought to Pass with Amendments #2025-2049s, #2025-2487S, #2025-2665s, and #2025-2710s",
           date="2025-06-05"),
        ev("H", "House Non-Concurs with Senate Amendment 2025-2049s 2025-2487S 2025-2665s and "
                "2025-2710s and Requests CofC (Rep. Kofalt): MA VV 06/05/2025", "floor", "MA",
           "House Non-Concurs with Senate Amendment 2025-2049s 2025-2487S 2025-2665s and "
           "2025-2710s and Requests CofC", date="2025-06-05"),
        ev("S", "Sen. Abbas Accedes to House Request for Committee of Conference, MA, VV; "
                "(In recess 06/05/2025)", "floor", "MA",
           "Accedes to House Request for Committee of Conference", date="2025-06-05"),
        ev("S", "Conference Committee Report; Not Signed Off", date="2025-06-19"),
        ev("H", "Conference Committee Report: Not Filed", date="2025-07-08"))
    sb460 = _nar(
        ev("S", "Ought to Pass: MA, VV; OT3rdg; 02/05/2026", "floor", "MA", "Ought to Pass",
           date="2026-02-05"),
        ev("H", "Ought to Pass with Amendment 2026-1286h: MA VV 04/23/2026", "floor", "MA",
           "Ought to Pass with Amendment 2026-1286h", date="2026-04-23"),
        ev("S", "Sen. Gannon Moved Nonconcur with the House Amendment; Requests C of C, MA, VV; "
                "(In Recess 04/23/2026)", "floor", "MA",
           "Nonconcur with the House Amendment; Requests C of C", date="2026-04-23"),
        ev("H", "House Accedes to Senate Request for CofC (Rep. Roy): MA VV 05/14/2026", "floor", "MA",
           "House Accedes to Senate Request for CofC", date="2026-05-14"),
        ev("H", "Conference Committee Report: Not Filed", date="2026-06-01"))
    hb291 = _nar(
        ev("H", "Ought to Pass : MA DV 191-179 04/08/2021", "floor", "MA", "Ought to Pass",
           date="2021-04-08"),
        ev("S", "Ought to Pass with Amendment 2021-1674s, MA, VV; OT3rdg; 05/27/2021", "floor", "MA",
           "Ought to Pass with Amendment 2021-1674s", date="2021-05-27"),
        ev("H", "House Non-Concurs with Senate Amendment 2021-1674s and Requests CofC (Reps. "
                "Torosian, B. Griffin, Groen, Mooney): MA VV 06/04/2021", "floor", "MA",
           "House Non-Concurs with Senate Amendment 2021-1674s and Requests CofC (Reps. Torosian, "
           "B. Griffin, Groen, Mooney)", date="2021-06-04"),
        ev("S", "Sen. Gray Accedes to House Request for Committee of Conference, MA, VV; 06/10/2021",
           "floor", "MA", "Accedes to House Request for Committee of Conference", date="2021-06-10"),
        ev("S", "Conference Committee Report; Not Signed Off", date="2021-06-23"))
    sb65 = _nar(
        ev("S", "PASSED/ADOPTED WITH AM", "floor", "MA", "Ought to Pass with Amendment",
           date="1989-02-16"),
        ev("H", "PASSED/ADOPTED WITH AM; HJ81, P2485-2486 + 2533", "floor", "MA",
           "Ought to Pass with Amendment", date="1989-05-04"),
        ev("S", "SENATE NONCONCUR WITH HOUSE AM, REQ CONF COMM", "floor", "MA", "Nonconcur",
           date="1989-05-11"),
        ev("H", "HOUSE ACCEDED TO REQ FOR CONF COMM, REP FRASER MA VV", "floor", "MA",
           "Accede to Request for Committee of Conference", date="1989-05-16"),
        ev("S", "DIED IN COMMITTEE OF CONFERENCE", date="1989-05-24"))
    sitting = {"gen_status": "SENATE", "house_status": "CONFERENCE COMMITTEE",
               "senate_status": "CONFERENCE COMMITTEE"}
    ended = {"gen_status": "SENATE", "house_status": "DIED, SESSION ENDED",
             "senate_status": "CONFERENCE COMMITTEE"}
    for bid, term, st, n, was, says in (
            ("HB1323", "2025-2026", {"gen_status": "SENATE", "senate_status": "CONFERENCE COMMITTEE"},
             hb1323, "In a committee of conference", "no report was signed"),
            ("HB243", "2025-2026", ended, hb243, "Died when the session ended", "no report was signed"),
            ("SB460", "2025-2026", {"house_status": "DIED, SESSION ENDED"}, sb460,
             "Died when the session ended", "no report was filed"),
            ("HB291", "2021-2022", {"gen_status": "SENATE",
                                    "house_status": "NONCONCURRED REQUEST CONFERENCE",
                                    "senate_status": "CONFERENCE COMMITTEE"}, hb291,
             "One chamber did not concur; a committee of conference was asked for",
             "no report was signed"),
            ("SB65", "1989-1990", sitting, sb65, "In a committee of conference",
             "the bill died in the committee")):
        # What the label was without the docket's word: the check is about
        # these classes, so a fixture that stopped reaching them fails too.
        without = [e for e in n["events"]
                   if not re.search(r"not signed|not filed|died in comm", e["raw"], re.I)]
        d = B.bill_disposition({}, bid, st, _nar(*without), [], term, "2025-2026",
                               term_over=True)
        if d.status != was:
            bad.append(f"{bid} of {term} no longer starts from {was!r} ({d.status!r})")
        d = B.bill_disposition({}, bid, st, n, [], term, "2025-2026", term_over=True)
        if (d.kind, d.status) != ("done", B.CONF_UNABLE) or not d.between or d.stale:
            bad.append(f"{bid} of {term}: {(d.kind, d.status, d.between, d.stale)}")
            continue
        end = (B.closing_stage(d.status, n, decided=True) or {}).get("text", "")
        if says not in end or "reported" in end:
            bad.append(f"{bid}: How it ended reads {end!r}")
        _intro, steps = B.journey(n, bid, [], "", "", term)
        if any("could not agree" in s["text"] for s in steps):
            bad.append(f"{bid}: a line of How it got here was rewritten, and no chamber adopted a report")
        passed = {c for c in "HS" if B.journey_state(steps, c) == "p"}
        acted = list(dict.fromkeys(s["body"] for s in steps if s["body"] in "HS"))
        rail = B.passage(n.get("stages"), d.kind, d.status, bid, passed, acted)
        why = B.journey_disagrees(steps, d.kind, d.status, rail, bid)
        if why:
            bad.append(f"{bid}: the journey disagrees with its status: {why}")
    # HB 1091 of 2026: "Not Signed Off" at the deadline, then report
    # 2026-2022c filed and adopted by the Senate, and the House refusing to
    # suspend its rules for the late report. Same-day rows are not reliably
    # in order, so both orders are tried; and without the House's row, the
    # Senate's adoption alone says a report was signed.
    head = [ev("H", "Ought to Pass with Amendment 2026-0657h: MA VV 03/05/2026", "floor", "MA",
               "Ought to Pass with Amendment 2026-0657h", date="2026-03-05"),
            ev("S", "Ought to Pass with Amendment # 2026-1544s, MA, VV; OT3rdg; 04/23/2026", "floor",
               "MA", "Ought to Pass with Amendment # 2026-1544s", date="2026-04-23"),
            ev("H", "House Non-Concurs with Senate Amendment 2026-1544s and Requests CofC (Rep. Roy): "
                    "MA VV 04/23/2026", "floor", "MA",
               "House Non-Concurs with Senate Amendment 2026-1544s and Requests CofC",
               date="2026-04-23"),
            ev("S", "Sen. Gannon Accedes to House Request for Committee of Conference, MA, VV; "
                    "(In recess 05/07/2026)", "floor", "MA",
               "Accedes to House Request for Committee of Conference", date="2026-05-07")]
    filed = ev("S", "Conference Committee Report Filed, # 2026-2022c; 06/04/2026", date="2026-06-04")
    adopted = ev("S", "Conference Committee Report # 2026-2022c, Adopted, VV; 06/04/2026",
                 date="2026-06-04")
    unsigned = ev("S", "Conference Committee Report; Not Signed Off", date="2026-06-04")
    refused = ev("H", "Rules suspension to consider late sign off report at the present time "
                      "MF DV 180-156", date="2026-06-05")
    for rows in ((filed, adopted, unsigned, refused), (unsigned, filed, adopted, refused),
                 (filed, adopted, unsigned)):
        n = _nar(*head, *rows)
        d = B.bill_disposition({}, "HB1091", {"gen_status": "SENATE",
                                             "house_status": "DIED, SESSION ENDED",
                                             "senate_status": "CONFERENCE REPORT ADOPTED"},
                               n, [], "2025-2026", "2025-2026", term_over=True)
        if d.status != "Died when the session ended":
            bad.append(f"HB1091 of 2026, whose conferees signed late: {d.status!r}")
        _intro, steps = B.journey(n, "HB1091", [], "", "", "2025-2026")
        said = [s["text"] for s in steps if s["act"] == "conf_adopted"]
        if not said or any("could not agree" in t for t in said):
            bad.append(f"HB1091 of 2026: the Senate's adoption of report 2026-2022c reads {said!r}")
    # HB 1410 of 2002: "(Conf Comm Report Not Signed)", and the next day the
    # Senate refused to allow a report after the deadline.
    n = _nar(ev("H", "Comm Am, AA VV; Rep Gilmore Fl Am{2897}, AL DIV(117-162); Passed with Am VV; "
                     "HJ26, p1085-1086", "floor", "MA", "Ought to Pass with Amendment",
                date="2002-03-07"),
             ev("S", "Ought to Pass with Amendment {3464},(New Title), Division 13y- 11n, AA", "floor",
                "MA", "Ought to Pass with Amendment", date="2002-04-16"),
             ev("H", "House Nonconc with Sen Am req Conf Comm, Rep Patten MA VV; HJ38, p1442", "floor",
                "MA", "Nonconcur", date="2002-04-25"),
             ev("S", "Sen. Roberge Accede to House Request for Committee of Conference, MA, VV",
                "floor", "MA", "Sen. Roberge Accede to House Request for Committee of Conference",
                date="2002-04-25"),
             ev("H", "(Conf Comm Report Not Signed)", date="2002-05-01"),
             ev("S", "Sen. Wheeler Rules Suspension; To Allow C of C Report After Deadline 2/3 nec., MF",
                date="2002-05-02"))
    d = B.bill_disposition({}, "HB1410", sitting, n, [], "2001-2002", "2025-2026")
    if d.status != "In a committee of conference":
        bad.append(f"HB1410 of 2002, a report the Senate would not allow late: {d.status!r}")
    # HB 723 of 1997: its report of no agreement was rejected, and the new
    # conference the chambers formed never reported. That one is the last.
    n = _nar(ev("H", "HOUSE NONC WITH SEN AM REQ CONF COMM, REP A MERRILL MA; HJ70", "floor", "MA",
                "Nonconcur and Request Committee of Conference", date="1997-05-29"),
             ev("S", "SEN ACCEDED TO REQ FOR CONF COMM, SEN D WHEELER MA VV; SJ22,P484-", "floor",
                "MA", "Accede to Request for Committee of Conference", date="1997-05-29"),
             ev("S", "CONF COMM REPORT (UNABLE TO AGREE) FILED", date="1997-06-05"),
             ev("S", "CONF COMM REPT, ML DIV(10-13); SEN MCCARLEY MOVED TO DISCHARGE",
                date="1997-06-10"),
             ev("S", "CONF COMM, REQ NEW CONF COMM, MA RC(13-10); SJ23(I),P552", date="1997-06-10"),
             ev("H", "HOUSE ACCEDED TO REQ FOR NEW CONF COMM, REP R FOSTER MA VV; HJ73, P2092",
                "floor", "MA", "Accede to Request for Committee of Conference", date="1997-06-10"),
             ev("H", "CONF COMM MEETING JUN11 11:00 RM205,LOB", "conference_meeting",
                date="1997-06-11"))
    d = B.bill_disposition({}, "HB723", sitting, n, [], "1997-1998", "2025-2026")
    if d.status != "In a committee of conference":
        bad.append(f"HB723 of 1997, whose new conference never reported: {d.status!r}")
    # And nothing after it may carry the bill on. Two of HB 1210 of 2002's
    # rows, without the new conference that came between them: a report not
    # signed, then the bill enrolled -- which is not a bill that died.
    if B.conference_failure([ev("S", "Conference Committee Report [Not Signed]", date="2002-05-02"),
                             ev("H", "Enrolled; HJ44, p1533", "enrolled", date="2002-05-02")]):
        bad.append("an enrolled bill read as conferees who never signed a report")
    assert not bad, "; ".join(bad)
    return "ok", ("not signed, not filed and died in conference end the bill as a report of no "
                  "agreement does; a late report and a new conference keep their labels")


@check("status", "the constitution page counts each CACR of the term once",
       needs=("build_civics",))
def _cacr_partition(build_civics):
    """The page said "7 were killed outright, 16 died when the session ended,
    4 passed one chamber and stopped, and the rest are still in committee or
    were postponed" -- the same three CACRs in two counts, a "rest" that was
    six three-fifths failures and a death on the table, and "None of them
    reached the voters" beside CACR 13 on its way to the November ballot.
    Every CACR is now in one clause, and a clause with nothing in it is not
    printed.

    Then the page said "9 CACRs won a majority of those voting in the House
    and still fell short" and, a paragraph later, "6 fell short of three
    fifths on the House floor". The docket has 10. CACR 8 of 2025's line says
    "Lacking Necessary Two-Thirds Vote", a clerk's slip for three fifths, and
    was not read; CACR 8, 11, 12 and 18 each lost a House vote they had a
    majority on and were counted only as dying when the session ended. Both
    paragraphs now count one test, and the rows below are the real docket
    lines of those CACRs (and of 2016's CACR 17, whose line names no
    threshold at all)."""
    BC = build_civics

    def ev(body, raw):
        return {"body": body, "raw": raw}

    def nar(*evs):
        return {"events": list(evs)}

    fifths = nar(ev("H", "Ought to Pass: MF RC 194-158 Lacking Necessary Three-Fifths Vote 03/05/2026"))
    rows = ([{"id": "CACR13", "status": "Passed both chambers, goes to the voters in November 2026",
              "passage": "Hpp--"}]
            + [{"id": f"CACR{i}", "status": "Killed", "passage": "Hx--x"} for i in range(20, 27)]
            + [{"id": f"CACR{i}", "status": "Failed to pass", "passage": "Hx--x"} for i in range(30, 36)]
            + [{"id": "CACR40", "status": "Died on the table", "passage": "Hx--x"}]
            + [{"id": f"CACR{i}", "status": "Died when the session ended", "passage": "Spx-x"}
               for i in range(41, 44)]
            + [{"id": f"CACR{i}", "status": "Died when the session ended", "passage": "Hx--x"}
               for i in range(50, 63)])
    narr = {f"CACR{i}": fifths for i in range(30, 35)}
    narr.update({
        "CACR35": nar(ev("H", "Ought to Pass: MF RC 188-135 03/09/2016")),
        "CACR40": nar(ev("H", "Lay CACR22 on Table (Rep. Hill): MA RC 175-153 03/05/2026"),
                      ev("H", "Remove from Table (Rep. H. Howard): MF DV 100-230 03/11/2026")),
        # CACR 8 of 2025, 11 and 12 of 2026: through the Senate, short in the House.
        "CACR41": nar(ev("S", "Ought to Pass, RC 21Y-3N, MA, by Necessary 3/5; OT3rdg; 03/13/2025"),
                      ev("H", "Ought to Pass: MF DV 203-158 Lacking Necessary Two-Thirds Vote 05/08/2025")),
        "CACR42": nar(ev("S", "Ought to Pass with Amendments #2026-1219s, RC 23Y-1N, by necessary 3/5, "
                              "MA; OT3rdg; 03/26/2026"),
                      ev("H", "Ought to Pass: MF RC 199-157 Lacking Necessary Three-Fifths Vote 04/23/2026")),
        "CACR43": nar(ev("S", "Ought to Pass, RC 16Y-8N, MA, by Necessary 3/5; OT3rdg; 02/19/2026"),
                      ev("H", "Amendment # 2026-1134h: AA RC 192-148 05/14/2026"),
                      ev("H", "Ought to Pass with Amendment 2026-1134h: MF RC 193-148 Lacking "
                              "Necessary Three-Fifths Vote 05/14/2026")),
        # CACR 18 of 2026, short; CACR 9, no majority; CACR 19, not a vote on passing it.
        "CACR50": nar(ev("H", "Ought to Pass: MF DV 170-163 Lacking Necessary Three-Fifths Vote 03/12/2026")),
        "CACR51": nar(ev("H", "Ought to Pass: MF DV 136-185 Lacking Necessary Three-Fifths Vote 03/11/2026")),
        "CACR52": nar(ev("H", "Special Order to next order of business (Rep. A. Murray): MF DV 115-220 "
                              "03/11/2026")),
    })
    got = BC._cacr_record(rows, narr, "2025-2026")
    want = ("The 2025&ndash;2026 term filed <b>31 CACRs</b>. One passed both chambers and goes "
            "to the voters at the state general election in November 2026. 7 were killed "
            "outright; 10 fell short of three fifths on the House floor, 3 of them after "
            "passing the Senate; 1 died on the table; and 12 died when the session ended.")
    assert got == want, f"got {got!r}"
    # The paragraph above it counts the same failures by the same test.
    idx = ([dict(r, term="2025-2026") for r in rows]
           + [{"id": "CACR26", "term": "2011-2012", "passage": "Hpp--",
               "status": "Passed both chambers, went to the voters"}])
    hurdle = BC._cacr_hurdle(idx, {"2025-2026": narr}, "2025-2026")
    assert ("Of the 32 CACRs filed since 2011, 2 passed both chambers." in hurdle
            and "In the 2025&ndash;2026 term, 10 CACRs won a majority of those voting "
                "in the House and still fell short." in hurdle), hurdle
    assert "%" not in hurdle and "margin" not in hurdle, (
        "the hurdle paragraph measures a CACR's margin against those voting: " + hurdle)
    # CACR 26 of 2012 fell two short and was carried on reconsideration.
    cacr26 = nar(ev("H", "Ought to Pass: MF RC 237-115 Lacking Necessary Three-Fifths Vote"),
                 ev("H", "Reconsideration of OTP (Rep Hess): MA RC 242-111"),
                 ev("H", "Ought to Pass: MA RC 239-114 By Necessary Three-Fifths Vote"))
    assert not BC._fell_short(cacr26, "Died when the session ended"), "a CACR the House carried fell short"
    one = BC._cacr_record([{"id": "CACR1", "status": "Killed", "passage": "Hx--x"}], {}, "2023-2024")
    assert "None passed both chambers. 1 was killed outright." in one, one
    assert " 0 " not in got and "no of" not in one, (got, one)
    assert BC._cacr_record([], {}, "2023-2024").endswith("filed no CACRs."), "an empty term"
    return "ok", "31 CACRs in five clauses, each counted once, and the same 10 short on both paragraphs"


# =============================================================== code: naming ==

@check("naming", "members are named the same way everywhere",
       needs=("build_site_v2",))
def _naming(build_site_v2):
    m = build_site_v2.member_labels
    cases = [
        (dict(chamber="H", party="R", district="13", county="Rockingham"),
         "Nelson, Jodi", "Rep. Jodi Nelson (R)", "Rep. Jodi Nelson (R - Rock 13)"),
        (dict(chamber="S", party="D", district="24"),
         "Altschiller, Debra", "Sen. Debra Altschiller (D)",
         "Sen. Debra Altschiller (D - SD24)"),
        (dict(chamber="H", party="R", district="13", county="Rockingham"),
         "Rep. Jodi Nelson (R)", "Rep. Jodi Nelson (R)",
         "Rep. Jodi Nelson (R - Rock 13)"),
        # build_data's composite label keeps its own punctuation; what the
        # site draws does not. The abbreviation lost its trailing point so
        # that a member named from the roster and one named from
        # former_members.json read alike -- the difference used to track
        # exactly who had left office.
        (dict(chamber="H", party="R", district="13", county="Rockingham"),
         "Nelson, Jodi(R) Rock 13", "Rep. Jodi Nelson (R)",
         "Rep. Jodi Nelson (R - Rock 13)"),
        (dict(chamber="H", district="7", county="Merrimack"),
         "Doe, Pat", "Rep. Pat Doe", "Rep. Pat Doe (Merr 7)"),
        (dict(chamber="H", party="R"),
         "Doe, Pat", "Rep. Pat Doe (R)", "Rep. Pat Doe (R)"),
    ]
    wrong = []
    for kw, name, want_short, want_full in cases:
        lab = m(name, **kw)
        if lab["display"] != want_short or lab["display_full"] != want_full:
            wrong.append(f"{name!r} -> {lab['display']} / {lab['display_full']}")
    assert not wrong, "; ".join(wrong)
    assert m("Nelson, Jodi", chamber="H")["sort"] == "nelson, jodi"
    return "ok", "6 shapes including the composite label and the missing party"


@check("naming", "an unnamed member is not dressed up as a person",
       needs=("build_site_v2",))
def _placeholder(build_site_v2):
    lab = build_site_v2.member_labels("Member #377204", chamber="H", party="R")
    assert lab["display"] == "Member #377204", lab["display"]
    return "ok", "no honorific, no party letter"


# ========================================================== code: roll calls ==

SUMMARY_LINE = ("2026|H|123|03/06/2026 11:12:09 AM|HB1442|197|151|24|23|0|0|"
                "Ought to Pass|relative to something\n")


@check("rollcalls", "yeas and nays come from fields 5 and 6",
       needs=("rollcall_parser",))
def _cols(rollcall_parser):
    d = Path(tempfile.mkdtemp())
    try:
        f = d / "RollCallSummary.txt"
        f.write_text(SUMMARY_LINE, encoding="utf-8")
        rows = rollcall_parser.parse(f)
        assert rows, "the canonical parser read nothing from a well-formed line"
        r = rows[0]
        assert (r["yeas"], r["nays"]) == (197, 151), (r["yeas"], r["nays"])
        return "ok", f"{r['bill']} {r['yeas']}-{r['nays']}, fields 7/8 are the "
        f"{r['not_voting']} who did not vote"
    finally:
        shutil.rmtree(d, ignore_errors=True)


@check("rollcalls", "a vote on a House rule is not filed as a bill",
       needs=("rollcall_parser",))
def _rule_vote_not_a_bill(rollcall_parser):
    """The House amended its own Rule 64 twice on 8 January 2025.

    Both votes are filed in RollCallSummary.txt under "HRULE64", which passes
    for a bill number if the test is letters-then-digits, and gave the site a
    bill that does not exist and no page could ever show. A vote about the
    chamber's own rules is procedural, which is a category this already has.
    """
    d = Path(tempfile.mkdtemp())
    try:
        f = d / "RollCallSummary.txt"
        f.write_text("\n".join([
            "2025|H|1|1/8/2025 10:00:00 AM|HRULE64|216|164|10|10|||"
            "Amend H Rule 64|relating to the rules of the House",
            "2025|H|2|1/8/2025 11:00:00 AM|HB56|216|154|20|8|||"
            "Inexpedient to Legislate|relative to something",
        ]) + "\n", encoding="utf-8")
        rows = {r["bill"]: r for r in rollcall_parser.parse(f)}
        assert "HRULE64" in rows, "the rule vote was dropped, not reclassified"
        assert rows["HRULE64"]["procedural"], (
            "a vote to amend a House rule is filed as a vote on a bill")
        assert not rows["HB56"]["procedural"], (
            "a real bill's vote was swept up as procedural")
        return "ok", "the rule vote is procedural and the bill's is not"
    finally:
        shutil.rmtree(d, ignore_errors=True)


