@check("session", "a docket row filed under the wrong bill leaves its history and says whose it is",
       needs=("narrative", "build_site_v2"))
def _session_misfiled_row(N, B):
    """HB 1364 of 2026 carried a roll call that belongs to HB 1824: "Special
    Order next order of business (Rep. Luneau): MF RC 151-180 03/12/2026 HJ
    7". The House Journal of 11 March and the roll call put that vote on HB
    1824, and its history read "the House failed ... on a roll call 151-180"
    and put it on the House's 12 March sitting. docket_corrections.json's
    "misfiled" entry takes the row out of HB 1364's history and keeps it, with
    a note, among the docket's own lines; HB 1824's row of the vote says the
    docket files it twice. An entry whose row changes is reported and not
    applied."""
    import contextlib
    import io
    saved = (N.MISFILED, set(N.MOVED), N.CORRECTIONS, N.TERM)
    root = Path(tempfile.mkdtemp())
    entry = {"session": "2026", "bill": "HB1364", "body": "H",
             "source_says": "Special Order next order of business (Rep. Luneau): MF RC "
                            "151-180 03/12/2026 HJ 7",
             "belongs_to": "HB1824",
             "belongs_to_says": "Special Order to next order of business (Rep. Damon): MF "
                                "RC 151-180 03/11/2026 HJ 7 P. 103",
             "note": "This vote was not on HB 1364.", "note_there": "Also under HB 1364."}
    try:
        def build(lines):
            (root / "Docket.txt").write_text("\n".join(lines) + "\n", encoding="utf-8")
            N.MISFILED, N.CORRECTIONS = [entry], []
            N.MOVED.clear()
            out, said = {}, io.StringIO()
            for b, rows in N.parse_docket(str(root / "Docket.txt")).items():
                N.TERM = N.P.term_of(rows[0]["session"])
                out[b] = N.build(b, rows)
            with contextlib.redirect_stdout(said):
                N.report_corrections({"2025-2026": out})
            return out, said.getvalue()

        out, said = build(DOCKET_HB1364)
        h, t = out["HB1364"], out["HB1824"]
        assert not any("151-180" in e["raw"] for e in h["events"]) and "151" not in h["narrative"], (
            f"HB 1364 still tells HB 1824's vote: {h['narrative'][-90:]!r}")
        away = h.get("misfiled") or []
        assert len(away) == 1 and away[0]["belongs_to"] == "HB1824" and away[0]["row_note"], (
            f"the misfiled row was not kept with its note: {away!r}")
        mine = [e for e in t["events"] if "151-180" in e["raw"]]
        assert mine and mine[0].get("row_note") == "Also under HB 1364.", (
            f"HB 1824's own row of the vote has no note: {mine!r}")
        lines = B.docket_lines(h)
        assert [e["date"] for e in lines] == sorted(e["date"] for e in lines) and any(
            e.get("row_note") for e in lines), "the page's docket lines lost the misfiled row"
        assert "taken off" in said, f"the applied entry was not reported: {said!r}"
        # And the page draws the note under the line, as it draws a date's.
        js, stub = Path("app.js"), Path("dom_stub.js")
        if js.exists() and stub.exists() and shutil.which("node"):
            row = {"id": "HB1364", "year": 2026, "term": "2025-2026", "title": "",
                   "status": "Died when the session ended", "kind": "done", "passage": "Hx--x"}
            d = {**row, "events": [{"date": e["date"], "text": e["raw"],
                                    **({"row_note": e["row_note"]} if e.get("row_note") else {})}
                                   for e in lines]}
            (root / "page.js").write_text(js.read_text(encoding="utf-8"), encoding="utf-8")
            (root / "stub.js").write_text(stub.read_text(encoding="utf-8"), encoding="utf-8")
            (root / "d.json").write_text(json.dumps([row, d]), encoding="utf-8")
            (root / "go.js").write_text("""
require("./stub.js");
const fs = require("fs");
const scope = (0, eval)(fs.readFileSync("./page.js", "utf8")
  + "; ({renderDetail, detail, dkey, IDX, setFocused:(x)=>{focused=x;}})");
const [row, d] = JSON.parse(fs.readFileSync("./d.json", "utf8"));
scope.IDX.push(row);
scope.detail[scope.dkey(row.id)] = d;
scope.setFocused(row.id);
process.stdout.write("\\n@@" + JSON.stringify(scope.renderDetail(row, d)));
""", encoding="utf-8")
            r = _run(["node", "go.js"], cwd=root, capture_output=True, text=True, timeout=90)
            assert r.returncode == 0 and "@@" in (r.stdout or ""), (
                "app.js did not draw the docket under node: " + (r.stderr or r.stdout or "")[-300:])
            assert "This vote was not on HB 1364." in json.loads(r.stdout.rsplit("@@", 1)[1]), (
                "the page does not draw the misfiled row's note under it")
        # The General Court re-words the row: the entry stops, and says so.
        again, said = build([x.replace("(Rep. Luneau)", "(Rep. D. Luneau)") for x in DOCKET_HB1364])
        assert any("151-180" in e["raw"] for e in again["HB1364"]["events"]) and "NOT applied" in said, (
            "an entry whose row no longer reads as it says was applied, or not reported")
        return "ok", ("the vote leaves HB 1364's history and stays on its docket with a note; "
                      "HB 1824's row says so; a stale entry is reported")
    finally:
        N.MISFILED, N.CORRECTIONS, N.TERM = saved[0], saved[2], saved[3]
        N.MOVED.clear()
        N.MOVED.update(saved[1])
        shutil.rmtree(root, ignore_errors=True)


@check("session", "the clerk's as-of date dates a row, but never ahead of what it answers",
       needs=("narrative", "docket_vocab"))
def _session_as_of_dates(N, V):
    """A database-era floor row that states no date is dated by the moment it
    was entered -- unless the clerk wrote the day it was done.

    "[done during 1/4/2012 morning veto session]" was entered on 30 November
    2011 and put four of January's veto votes on a November page. But
    "[Recess of 6/5/13]" names the sitting the House was in recess of, and
    dated by it HB 224's non-concurrence would come a day BEFORE the Senate
    amendment it refused; the Senate's "[05/06/04]" on HB 369 would have it
    accede to a House request six days before the House made it. Real rows,
    each case once.
    """
    from datetime import datetime as _dt
    saved = (N.CORRECTIONS, N.TERM)
    rows = {
        ("HB218", "2011"): [
            "2011|0291|11/30/2011 09:57:16 AM|HB218|H|Veto Sustained: RC 231-128 "
            "Lacking Rquired Two Thirds Vote, [done during 1/4/2012 morning veto "
            "session]; HJ 76, PG.2297-2300|11/30/2011 09:57:16 AM"],
        ("HB224", "2013"): [
            "2013|0305|06/06/2013 10:43:40 AM|HB224|S|Ought to Pass with Amendment "
            "1947s, MA, VV; OT3rdg|06/06/2013 10:43:40 AM",
            "2013|0305|06/12/2013 11:14:47 AM|HB224|H|House Non-Concurs with Senate "
            "AM #1947s and Requests C of C (Rep. Shurtleff): MA VV [Recess of "
            "6/5/13]; HJ49, PG.1650|06/12/2013 11:14:47 AM"],
        ("HB369", "2004"): [
            "2004|0125|05/06/2004 09:36:17 PM|HB369|S|Ought to Pass as Amended{1544},"
            "(New Title), MA, VV; OT3rdg; SJ 15, Pg.448|05/06/2004 09:36:17 PM",
            "2004|0125|05/13/2004 10:54:26 AM|HB369|H|House Nonconc with Sen Am req "
            "Conf Comm, Rep Mock MA VV;   HJ 39, p 1547|05/13/2004 10:54:26 AM",
            "2004|0125|05/13/2004 04:39:38 PM|HB369|S|Senator Peterson Accede to House "
            "Request for C of C, MA, VV [05/06/04]; SJ 15-A, Pg.466|05/13/2004 04:39:38 PM"],
        ("HB189", "2001"): [
            "2001|0133|05/09/2001 09:37:36 AM|HB189|S|Special Order To [05/17/01], MA, "
            "VV; SJ 12, Pg.262|05/09/2001 09:37:36 AM"],
        # AN ENROLMENT DONE IN RECESS is not told before the vote it enrolled:
        # SB 48 of 2015 was "enrolled" on 9 April, six days before the House
        # passed it. HB 1110 of 2014's, done in recess after both votes,
        # keeps the day it names.
        ("SB48", "2015"): [
            "2015|0118|04/15/2015 11:02:16 AM|SB48|H|Ought to Pass: MA VV; HJ 34, PG. 1554"
            "|04/15/2015 11:02:16 AM",
            "2015|0118|04/29/2015 12:29:48 PM|SB48|S|Enrolled (In recess 4/9/2015); SJ 12"
            "|04/29/2015 12:29:48 PM"],
        ("HB1110", "2014"): [
            "2014|2053|05/08/2014 11:20:14 AM|HB1110|S|Ought to Pass: MA, VV; OT3rdg; SJ 12"
            "|05/08/2014 11:20:14 AM",
            "2014|2053|05/22/2014 06:31:24 PM|HB1110|H|Enrolled (In recess of 5/15/2014)"
            "|05/22/2014 06:31:24 PM"],
        # Nor after the governor it went to: SB 447 of 2016 was entered five
        # days after the signature, and is told on the day of the House vote
        # before it. HB 273 of 2021's, entered the day the governor signed,
        # keeps that day, ahead of the signature.
        ("SB447", "2016"): [
            "2016|2955|1/20/2016 12:00:00 AM|SB447|H|Ought to Pass : MA DV 275-71 01/20/2016 "
            "HJ 8 P. 2|1/20/2016 12:00:00 AM",
            "2016|2955|1/26/2016 12:00:00 AM|SB447|S|Enrolled (In recess 01/14/2016); SJ 2"
            "|1/26/2016 12:00:00 AM",
            "2016|2955|4/20/2016 12:00:00 AM|SB447|S|Signed by the Governor on 01/21/2016; "
            "Chapter 0001 SJ 3|4/20/2016 12:00:00 AM"],
        ("HB273", "2021"): [
            "2021|0110|5/6/2021 12:00:00 AM|HB273|S|Ought to Pass : RC 23Y-0N, MA; OT3rdg; "
            "05/06/2021; SJ 14|5/6/2021 12:00:00 AM",
            "2021|0110|5/11/2021 12:00:00 AM|HB273|H|Enrolled (in recess of) 04/09/2021 HJ 7 "
            "P. 103|5/11/2021 12:00:00 AM",
            "2021|0110|5/12/2021 12:00:00 AM|HB273|H|Signed by Governor Sununu 05/11/2021; "
            "Chapter 30; Eff: 05/11/2021|5/12/2021 12:00:00 AM"],
        # A DAY'S ROWS IN THE ORDER THEY WERE ENTERED, dated or not: the
        # House defeated HB 705's conference report at 5:07 PM, reconsidered
        # at 5:08 and adopted it at 5:14. The two floor rows are dated at
        # midnight and "Defeated" by its minute, and the history put the
        # defeat last -- on a bill that became law.
        ("HB705", "2003"): [
            "2003|0462|06/24/2003 05:07:35 PM|HB705|H|Conf Comm Report Defeated "
            "RC(159-172);  HJ 51, p1628-1630|06/24/2003 05:07:35 PM",
            "2003|0462|06/24/2003 05:08:03 PM|HB705|H|Rep Mock moved to Reconsider, MA "
            "VV;  HJ 51, p1633|06/24/2003 05:08:03 PM",
            "2003|0462|06/24/2003 05:14:32 PM|HB705|H|Conf Comm Report Adopted VV; HJ 51, "
            "p1633|06/24/2003 05:14:32 PM"],
    }
    try:
        N.CORRECTIONS = []
        got, every, dated = {}, {}, {}
        for (bill, session), lines in rows.items():
            recs = []
            for x in lines:
                p = x.split("|")
                recs.append({"lsr": f"{p[0]}-{p[1]}", "session": p[0], "body": p[4],
                             "desc": p[5], "flags": [],
                             "created": _dt.strptime(p[2], "%m/%d/%Y %I:%M:%S %p")})
            N.TERM = N.P.term_of(session)
            evs = N.build(bill, recs)["events"]
            every[bill] = [e["raw"][:24] for e in evs]
            dated[bill] = [(e["date"], e["raw"][:8]) for e in evs]
            got[bill] = [(e["body"], e["date"], e["raw"][:24])
                         for e in evs if e["type"] in ("floor", "veto_override")]
        assert [x[:20] for x in every["HB705"]] == [
                "Conf Comm Report Def", "Rep Mock moved to Re", "Conf Comm Report Ado"], (
            f"a day's rows are not in the order the clerk entered them: {every['HB705']}")
        assert [d for _, d, _ in got["HB218"]] == ["2012-01-04"], (
            f"the clerk's 'done during 1/4/2012' did not date the veto vote: {got['HB218']}")
        assert ("H", "2013-06-12") in [(b, d) for b, d, _ in got["HB224"]], (
            "a row done in recess of 5 June 2013 was moved onto 5 June, ahead "
            f"of the Senate amendment it refused: {got['HB224']}")
        assert ("S", "2004-05-13") in [(b, d) for b, d, _ in got["HB369"]], (
            "the Senate's accession was dated before the House request it "
            f"answered: {got['HB369']}")
        # Put back on its own day, it must also go back to its place in it:
        # the House asked at 10:54 AM, the Senate acceded at 4:39 PM.
        assert [(b, d) for b, d, _ in got["HB369"]] == [
            ("S", "2004-05-06"), ("H", "2004-05-13"), ("S", "2004-05-13")], (
            "the Senate's accession, put back on 13 May, still comes before "
            f"the House request it answered that morning: {got['HB369']}")
        assert [d for _, d, _ in got["HB189"]] == ["2001-05-09"], (
            f"a special order's date was read as the day it was done: {got['HB189']}")
        enrolled = dated
        assert enrolled["SB48"] == [("2015-04-15", "Ought to"), ("2015-04-29", "Enrolled")], (
            "an enrolment done in recess was told before the House vote it "
            f"enrolled: {enrolled['SB48']}")
        assert enrolled["HB1110"][-1] == ("2014-05-15", "Enrolled"), (
            "an enrolment done in recess after both votes lost the day it "
            f"names: {enrolled['HB1110']}")
        assert enrolled["SB447"] == [("2016-01-20", "Ought to"), ("2016-01-20", "Enrolled"),
                                     ("2016-01-21", "Signed b")], (
            "an enrolment done in recess was told after the governor signed "
            f"the bill: {enrolled['SB447']}")
        assert enrolled["HB273"] == [("2021-05-06", "Ought to"), ("2021-05-11", "Enrolled"),
                                     ("2021-05-11", "Signed b")], (
            "an enrolment entered the day the governor signed lost that day or "
            f"its place ahead of the signature: {enrolled['HB273']}")
        return "ok", ("'done during' dates a veto vote; a day in recess, an "
                      "answer ahead of its request and a special order's "
                      "target date do not; a day's rows keep the order they "
                      "were entered in")
    finally:
        N.CORRECTIONS, N.TERM = saved


def _docket_rows(lines):
    """Docket.txt lines as the rows narrative.build() takes."""
    from datetime import datetime as _dt
    out = []
    for x in lines:
        p = x.split("|")
        out.append({"lsr": f"{p[0]}-{p[1]}", "session": p[0], "body": p[4],
                    "desc": p[5], "flags": [],
                    "created": _dt.strptime(p[2], "%m/%d/%Y %I:%M:%S %p")})
    return out


@check("narrative", "a day in the bill's own term keeps its year, a retained "
       "bill's introduction included, and the rail says the same day",
       needs=("narrative", "docket_vocab", "build_site_v2"))
def _history_term_dates(N, V, B):
    """A retained bill's session column is its SECOND year, on every row.

    HB 113 of 2005-2006 was introduced on organisation day, 1 December 2004,
    and retained into 2006, so its rows carry 2006. The rule that brings a
    clerk's slip back into the bill's session allowed a year either side of
    that -- 2005 to 2007 -- and "corrected" the introduction to 1 December
    2006: the history said the bill was introduced eleven months after the
    House killed it, told the introduction last, and the rail, finding it
    after the kill, left the Introduced stop undated. Twelve introductions of
    2005-2006 were entered on that December's days. A day in the term -- from
    the 1 November before it -- is the row's; a slip outside it is still
    brought back, and both are real rows.
    """
    saved = (N.CORRECTIONS, N.TERM, N.MISFILED)
    hb113 = [
        "2006|0168|12/01/2004 12:36:10 PM|HB113|H|Introduced and ref to Crim Just & PSfty;  "
        "HJ 6, p 83|12/01/2004 12:36:10 PM",
        "2006|0168|01/05/2005 04:38:24 PM|HB113|H|Hearing   Jan 13   10:00   RM204,LOB"
        "|01/05/2005 04:38:24 PM",
        "2006|0168|03/23/2005 10:11:29 AM|HB113|H|Retained in committee|03/23/2005 10:11:29 AM",
        "2006|0168|10/28/2005 10:39:45 AM|HB113|H|Comm Report for Jan 4, 2006; ITL  (vote "
        "15-0; CC); HC 2, p 127|10/28/2005 10:39:45 AM",
        "2006|0168|01/05/2006 09:13:33 AM|HB113|H|ITL [1/4/2006]  MA  HJ 7, pg 367"
        "|01/05/2006 09:13:33 AM"]
    # The clerk's slips, still brought back: a row stamped 1927 on a bill of
    # 1997, and "Enrolled 04/26/2089" on HB 1484 of 2018.
    hb685 = ["1997|0916|01/29/1927 06:31:47 PM|HB685|H|INTRODUCED AND REF TO CRIM JUST & "
             "PSFTY; HJ17,P280|01/29/1927 06:31:47 PM"]
    hb1484 = ["2018|2474|5/1/2018 12:00:00 AM|HB1484|H|Enrolled 04/26/2089|5/1/2018 12:00:00 AM"]
    try:
        N.CORRECTIONS, N.MISFILED = [], []
        # The rule itself, at its edges.
        assert N.in_term(2004, 12, 1, 2006) and N.in_term(2004, 11, 1, 2005), (
            "the December before a term's first year is not in the term")
        assert not N.in_term(2004, 10, 31, 2006) and not N.in_term(2007, 1, 1, 2006), (
            "a day outside the term was read as in it")
        assert N.session_keeps(2007, 6, 1, 2006) and not N.session_keeps(2004, 6, 1, 2006), (
            "the year either side of the session is no longer what it was")
        N.TERM = "2005-2006"
        rec = N.build("HB113", _docket_rows(hb113))
        evs = rec["events"]
        assert evs[0]["type"] == "introduced" and evs[0]["date"] == "2004-12-01", (
            "HB 113's introduction on 1 December 2004 is not its first event on "
            f"that day: {[(e['date'], e['type']) for e in evs]}")
        assert rec["narrative"].startswith("It was introduced on December 1, 2004"), (
            f"HB 113's history does not open with its introduction: {rec['narrative'][:120]!r}")
        assert "2006" not in rec["stages"][0]["text"].split(".")[0], (
            f"HB 113's introduction still carries 2006: {rec['stages'][0]['text'][:120]!r}")
        intro, _steps = B.journey(rec, "HB113", [], "", "", "2005-2006")
        assert intro == "2004-12-01", (
            f"the rail's Introduced stop for HB 113 reads {intro!r}, not the day "
            "the history gives it")
        N.TERM = "1997-1998"
        e = N.build("HB685", _docket_rows(hb685))["events"][0]
        assert e["date"] == "1997-01-29", f"a row stamped 1927 kept its year: {e['date']}"
        N.TERM = "2017-2018"
        e = N.build("HB1484", _docket_rows(hb1484))["events"][0]
        assert e["type"] == "enrolled" and e["date"] == "2018-04-26", (
            f"'Enrolled 04/26/2089' kept its year: {e['type']} {e['date']}")
        return "ok", ("HB 113 is introduced on 1 December 2004 in its history "
                      "and on its rail; slips of 1927 and 2089 are still "
                      "brought back")
    finally:
        N.CORRECTIONS, N.TERM, N.MISFILED = saved


@check("narrative", "a senator's motion is read as the senator's, never as passage",
       needs=("narrative", "docket_vocab", "session_days"))
def _senator_motions(N, V, SD):
    """The Senate clerk of 1999-2004 names the mover of a question after it,
    "Senate Accedes to Req for Conference Committee, Sen. McCarley, MA, VV",
    or before it with the outcome in words, "Senator Johnson Accede to House
    Request for C of C, Adopted [05/06/04]".

    The first read as a motion called "Sen. McCarley", which the Votes tab
    and the sitting page printed as the question put. The second read as the
    House's bare "Adopted", which is passage: 29 accessions and 27
    nonconcurrences of 2003-2004 said "the Senate voted to pass it", and the
    sitting pages "On the motion: Ought to Pass ... it carried in this
    chamber". Real rows, each shape once, and three that must not move.
    """
    saved = (N.CORRECTIONS, N.TERM, N.MISFILED)
    rows = {
        ("HB1148", "2003-2004"): [
            "2004|2305|05/13/2004 12:03:30 PM|HB1148|H|House Nonconc with Sen Am req Conf "
            "Comm, Rep Lawton MA VV;   HJ 39, p 1548|05/13/2004 12:03:30 PM",
            "2004|2305|05/13/2004 04:46:45 PM|HB1148|S|Senator Johnson Accede to House "
            "Request for C of C, Adopted [05/06/04]; SJ 15-A, Pg.469|05/13/2004 04:46:45 PM"],
        ("HB384", "2003-2004"): [
            "2004|0269|05/06/2004 03:25:13 PM|HB384|S|Senator Peterson Accede to House "
            "Request for Committee of Conference; Adopted; SJ 15-A, Pg.466"
            "|05/06/2004 03:25:13 PM"],
        ("SB61", "2003-2004"): [
            "2004|0278|05/06/2004 01:47:06 PM|SB61|S|Senator O'Hearn Nonconcur with House Am "
            "Requests Committee of Conference, Adopted; SJ 15-A, Pg.452|05/06/2004 01:47:06 PM"],
        ("HB265", "1999-2000"): [
            "1999|0051|06/29/1999 11:02:48 AM|HB265|S|Senate Accedes to Req for Conference "
            "Committee, Sen. McCarley, MA, VV|06/29/1999 11:02:48 AM",
            "1999|0051|07/01/1999 03:40:14 PM|HB265|S|Con Comm Report, Sen McCarley, MA, VV; "
            "SJ 27, P 758|07/01/1999 03:40:14 PM"],
        ("HB284", "1999-2000"): [
            "1999|0077|03/04/1999 02:08:23 PM|HB284|S|Sen. Krueger OTP, MA, VV; OT3rdg, MA, "
            "VV; SJ 6, P 70|03/04/1999 02:08:23 PM"],
        # Not to move: a question in words after the name, the House's own
        # "Adopted" on a resolution, and the Senate's "Sen Am" in a House row.
        ("HB733", "2003-2004"): [
            "2003|0006|06/05/2003 10:50:52 PM|HB733|S|Sen. Kenney Accede to House Request For "
            "Committee of Conference, MA, VV; SJ 19, Pg.662|06/05/2003 10:50:52 PM"],
        ("HCR3", "2003-2004"): [
            "2003|0227|01/30/2003 11:59:42 AM|HCR3|H|Adopted;  HJ 12, p221 + 231"
            "|01/30/2003 11:59:42 AM"],
        ("HB672", "2001-2002"): [
            "2002|0851|04/25/2002 12:46:29 PM|HB672|H|Sen Am, MA DIV(187-140);  HJ38, "
            "p1435-1437|04/25/2002 12:46:29 PM"],
    }
    try:
        N.CORRECTIONS, N.MISFILED = [], []
        floor = {}
        for (bill, term), lines in rows.items():
            N.TERM = term
            rec = N.build(bill, _docket_rows(lines))
            floor[bill] = [e for e in rec["events"] if e["type"] == "floor"]
            floor[bill + " text"] = rec["narrative"]

        def got(bill, i=-1):
            e = floor[bill][i]
            return e["action"], e["mover"], e["motion"]

        assert got("HB1148") == ("Accede to House Request for C of C", "Sen. Johnson", "MA"), (
            f"HB 1148's accession of 2004 reads {got('HB1148')}")
        assert got("HB384") == ("Accede to House Request for Committee of Conference",
                                "Sen. Peterson", "MA"), f"HB 384 of 2004 reads {got('HB384')}"
        assert got("SB61") == ("Nonconcur", "Sen. O'Hearn", "MA"), (
            f"SB 61 of 2004's nonconcurrence reads {got('SB61')}")
        for b in ("HB1148", "HB384", "SB61"):
            assert "voted to pass it" not in floor[b + " text"], (
                f"{b}'s history still says the Senate passed it: {floor[b + ' text']!r}")
        assert [got("HB265", i) for i in (0, 1)] == [
            ("Senate Accedes to Req for Conference Committee", "Sen. McCarley", "MA"),
            ("Con Comm Report", "Sen. McCarley", "MA")], (
            f"HB 265 of 1999 reads {[got('HB265', i) for i in (0, 1)]}")
        assert got("HB284") == ("Ought to Pass", "Sen. Krueger", "MA"), (
            f"HB 284 of 1999 reads {got('HB284')}")
        assert got("HB733") == ("Sen. Kenney Accede to House Request For Committee of "
                                "Conference", "", "MA"), f"HB 733 of 2003 moved: {got('HB733')}"
        assert got("HCR3") == ("Ought to Pass", "", "MA"), f"HCR 3 of 2003 moved: {got('HCR3')}"
        assert got("HB672") == ("Sen Am", "", "MA"), f"HB 672 of 2002 moved: {got('HB672')}"
        # And the sitting page's words for it.
        it = SD.Item("HB1148", "2003-2004", floor["HB1148"][-1], 0)
        assert it.action == "Accede to House Request for C of C" and it.mover == "Sen. Johnson", (
            f"the sitting page's motion is {it.action!r}, moved by {it.mover!r}")
        assert "carried in this chamber" not in it.outcome_words, (
            f"the sitting page says an accession carried the bill: {it.outcome_words!r}")
        return "ok", ("accessions and nonconcurrences of 2004 are the Senate's "
                      "motions, moved by a senator; the 1999 mover after the "
                      "question is the mover; three rows that must not move do not")
    finally:
        N.CORRECTIONS, N.TERM, N.MISFILED = saved


@check("session", "business done in recess is on its sitting, a joint rule's "
       "weekend is no sitting, and neither leaves a link behind",
       needs=("session_days", "build_session_pages"))
def _session_recess_and_rule_days(SD, BSP):
    """Thirteen sitting pages were for days the chamber did not sit.

    Ten were business done in the recess of an earlier sitting, which the
    docket enters on the day it was done and the journal prints with the
    sitting: "The House, Wednesday 12 June 2013" held sixteen refusals of
    Senate amendments that House Journal 49 of 5 June prints at pages 1650 to
    1653. Three were bills dying under a joint rule on a weekend deadline:
    "The House, Sunday 1 July 1990". The person decided on 24 September 2026
    that recess business goes on its sitting and a joint rule's date is no
    sitting; the bill histories are not touched.

    The rows are real docket wording, each form once, and the cases that must
    NOT move are real rows with one thing changed: a recess naming a day the
    chamber has no sitting on, one citing another journal than the sitting's,
    a recess the same day, and a joint-rule death on a weekday. Then the pages
    are built, over pages a
    previous build left, and nothing -- a page, a sitemap entry, a previous
    or next link -- may still point at a day that is gone.
    """
    def floor(date, body, raw, action, cite="", mover=""):
        return {"date": date, "body": body, "type": "floor", "raw": raw,
                "action": action, "motion": "MA", "vote_kind": "VV",
                "cite": cite, "mover": mover}
    nc = "House Non-Concurs with Senate AM #1947s and Requests C of C"
    acc = "Accede to House Request for C of C"
    ipjr = "Indefinitely Postpone"
    narr = {
        "2013-2014": {
            "HB528": {"events": [floor("2013-06-05", "H", "House Concurs with Senate "
                                       "AM #1486s (Rep J.MacKay): MA VV; HJ49, PG.1563",
                                       "House Concurs with Senate AM", "HJ 49")]},
            "HB224": {"events": [floor("2013-06-12", "H", nc + " (Rep. Shurtleff): MA "
                                       "VV [Recess of 6/5/13]; HJ49, PG.1650", nc,
                                       "HJ 49", "Rep. Shurtleff")]},
            # another journal than the sitting's: stays where it is entered
            "HB225": {"events": [floor("2013-06-13", "H", nc + " (Rep. Shurtleff): MA "
                                       "VV [Recess of 6/5/13]; HJ50, PG.1700", nc,
                                       "HJ 50", "Rep. Shurtleff")]},
            "HB650": {"events": [floor("2014-05-15", "H", "Concur with Senate Amendment "
                                       "#1339s (Rep. Bouchard) MA VV",
                                       "Concur with Senate Amendment")]},
            "HB498": {"events": [floor("2014-05-21", "H", "Rep. Chandler moved to "
                                       "Non-Concur with Senate AM and request C of C; "
                                       "MA VV (In recess of 5/15/14)", nc)]},
            # a recess of a day with no sitting: stays
            "HB499": {"events": [floor("2014-06-20", "H", "Rep. Chandler moved to "
                                       "Non-Concur with Senate AM and request C of C; "
                                       "MA VV (In recess of 6/18/14)", nc)]}},
        "2003-2004": {
            "HB369": {"events": [floor("2004-05-06", "S", "Ought to Pass as Amended"
                                       "{1544},(New Title), MA, VV; OT3rdg",
                                       "Ought to Pass as Amended", "SJ 15"),
                                 floor("2004-05-13", "S", "Senator Peterson " + acc +
                                       ", MA, VV [05/06/04]", acc, "SJ 15")]}},
        "2005-2006": {
            "HB114": {"events": [floor("2005-06-09", "S", "Sen. Kenney " + acc + ", MA, "
                                       "VV", acc, "SJ 21")]},
            # the clerk's slipped year, beside nine rows reading [06/09/05]
            "HB433": {"events": [floor("2005-06-16", "S", "Senator Morse " + acc +
                                       ", MA, VV, [06/09/04]", acc, "SJ 21")]}},
        "2025-2026": {
            "SB14": {"events": [floor("2025-06-05", "S", "Sen. Gannon Moved Nonconcur "
                                      "with the House Amendment; Requests C of C, MA, "
                                      "VV; (In Recess 06/05/2025)", "Nonconcur")]}},
        "1989-1990": {
            "HB381": {"events": [floor("1990-07-01", "H", "INDEFINITELY POSTPONED BY "
                                       "JOINT RULE 24(B)", ipjr)]},
            "HB575": {"events": [floor("1990-07-01", "H", "INDEFINITELY POSTPONED PER "
                                       "JT. RULE 24 (B)", ipjr)]},
            "HB1": {"events": [floor("1990-06-28", "H", "Ought to Pass: MA VV",
                                     "Ought to Pass")]}},
        "1995-1996": {
            "HB222": {"events": [floor("1995-07-01", "H", "INDEFINITELY POSTPONED PER JT "
                                       "RULE 23-A; HJ81,P2122", ipjr, "HJ 81")]},
            # a weekday deadline is a day the chamber may have sat: kept
            "HB1504": {"events": [floor("1996-06-13", "H", "INDEFINITELY POSTPONED PER "
                                        "JT RULE 23-A", ipjr)]}},
    }
    root = Path(tempfile.mkdtemp())
    try:
        (root / "narratives.json").write_text(json.dumps(narr), encoding="utf-8")
        days = SD.load(root / "narratives.json")

        def bills(body, date):
            d = days.get((body, date))
            return sorted(i.bill for i in d.items) if d else None
        want = {("H", "2013-06-05"): ["HB224", "HB528"],
                ("H", "2013-06-12"): None, ("H", "2013-06-13"): ["HB225"],
                ("H", "2014-05-15"): ["HB498", "HB650"], ("H", "2014-05-21"): None,
                ("H", "2014-06-20"): ["HB499"],
                ("S", "2004-05-06"): ["HB369", "HB369"], ("S", "2004-05-13"): None,
                ("S", "2005-06-09"): ["HB114", "HB433"], ("S", "2005-06-16"): None,
                ("S", "2025-06-05"): ["SB14"],
                ("H", "1990-07-01"): None, ("H", "1995-07-01"): None,
                ("H", "1990-06-28"): ["HB1"], ("H", "1996-06-13"): ["HB1504"]}
        got = {k: bills(*k) for k in want}
        assert got == want, "sittings are not as the journal holds them: " + "; ".join(
            f"{k[0]} {k[1]} has {got[k]}, want {want[k]}" for k in want if got[k] != want[k])
        entered = {i.bill: getattr(i, "entered", None)
                   for d in days.values() for i in d.items}
        assert entered["HB224"] == "2013-06-12" and entered["HB433"] == "2005-06-16" \
            and entered["HB528"] is None and entered["SB14"] is None \
            and entered["HB225"] is None, (
            f"a moved row lost the day the docket enters it, or an unmoved one "
            f"claims to have moved: {entered}")
        assert not SD.JOINT_RULE.search("SEN CONCURS WITH HOUSE AM TO JT RULES"), (
            "the Senate adopting joint rules was read as a bill dying under one")

        here = Path(".").resolve()
        if not (here / "bills.html").exists():
            return "ok", "sittings as the journal holds them; no bills.html to build pages"
        site = root / "site"
        shutil.copy2(here / "bills.html", root / "bills.html")
        base = "https://graniterecord.org"
        gone = ["2013-06-12", "2014-05-21", "1990-07-01", "1995-07-01"]
        (site / "session" / "H").mkdir(parents=True)
        for d in gone:
            (site / "session" / "H" / f"{d}.html").write_text("old", encoding="utf-8")
        (site / "sitemap.xml").write_text(
            '<?xml version="1.0"?><urlset>\n' + "".join(
                f"<url><loc>{base}/session/H/{d}.html</loc></url>\n" for d in gone)
            + "</urlset>", encoding="utf-8")
        r = _run([sys.executable, str(here / "build_session_pages.py"), "--site", "site",
                  "--base", base, "--body", "H"],
                 cwd=root, capture_output=True, text=True, timeout=180)
        assert r.returncode == 0, "build_session_pages: " + (r.stderr or r.stdout)[-300:]
        pages = {p.stem: p.read_text(encoding="utf-8")
                 for p in (site / "session" / "H").glob("*.html")}
        left = sorted(set(gone) & set(pages))
        assert not left, f"a page for a day that is no sitting is still on disk: {left}"
        sm = (site / "sitemap.xml").read_text(encoding="utf-8")
        dangling = [f"{d} from {k}" for k, html in pages.items() for d in gone
                    if f"{d}.html" in html] + [f"{d} from sitemap.xml" for d in gone
                                               if d in sm]
        assert not dangling, f"a link still reaches a day that is gone: {dangling}"
        page = pages.get("2013-06-05", "")
        assert "Done in the recess of this sitting" in page and \
            "Wednesday 12 June 2013" in page, (
            "the 5 June 2013 page does not say HB 224 was done in its recess and "
            "entered on 12 June, the date the bill's own history gives")
        return "ok", ("recess rows on their sitting with the docket's date beside "
                      "them, the guarded ones where they are; joint-rule weekends "
                      "are no sitting; no page, sitemap entry or neighbour link "
                      "reaches a day that went")
    finally:
        shutil.rmtree(root, ignore_errors=True)


@check("session", "recess business the docket does not mark is on its sitting "
       "too, and claims no speech made at it",
       needs=("session_days", "build_session_pages", "shell"))
def _session_unmarked_recess(SD, BSP, shell):
    """Two ways the recess fix of 24 September fell short.

    Most recess business says nothing of a recess. The House's refusals of
    Senate amendments entered on 24, 28 and 29 May 2024 cite HJ 14, and House
    Journal 14 prints every one under RECESS after the House recessed on
    23 May; the three days still built as sittings the House never held.
    The rows below are real docket rows, and the ones that must stay are real
    rows with one thing changed -- a count on the day, which a recess never
    takes, or no page to say where the journal prints it. The Senate's own
    refusals of 21 May 2008 cite SJ 18, the 15 May journal, and are printed
    in the 21 May sitting.

    And a moved row took the day's speeches. SB 389's accession, done in the
    recess of 15 May 2014 with no debate at all, was the bill's only row that
    day, so it claimed the five speeches made on the bill's floor amendments,
    whose tallies were 219-72 and 110-177; SB 148's, beside the roll call
    O'Brien and Tucker spoke on, made a second motion and pushed them off it.
    """
    def floor(date, body, raw, cite="", page=None, kind="VV", yeas=None,
              nays=None):
        return {"date": date, "body": body, "type": "floor", "raw": raw,
                "action": raw.split(":")[0].split(",")[0], "motion": "MA",
                "vote_kind": kind, "yeas": yeas, "nays": nays, "cite": cite,
                "cite_page": page}
    nc = "House Non-Concurs with Senate Amendment 2024-{}s and Requests CofC: MA VV {}"
    otp = "Ought to Pass: MA VV"
    narr = {
        "2023-2024": {
            "HB1": {"events": [floor("2024-05-23", "H", otp, "HJ 14", 10)]},
            "HB2": {"events": [floor("2024-05-23", "H", otp, "HJ 14", 20)]},
            "HB3": {"events": [floor("2024-05-23", "H", "Ought to Pass: MA RC 200-150",
                                     "HJ 14", 173, "RC", 200, 150)]},
            # entered the next day, no page: HJ 14 prints it on page 177
            "HB1695": {"events": [floor("2024-05-24", "H", nc.format(1621, "05/24/2024"),
                                        "HJ 14")]},
            "HB1030": {"events": [floor("2024-05-24", "H", nc.format(1544, "05/24/2024"),
                                        "HJ 14", 177)]},
            # no journal cited at all, on a day of nothing else
            "HB1521": {"events": [floor("2024-05-28", "H", nc.format(1968, "05/28/2024"))]},
            "HB1069": {"events": [floor("2024-05-28", "H", nc.format(1966, "05/28/2024"),
                                        "HJ 14", 178)]},
            # a day with a count is a sitting: stays
            "HB1593": {"events": [floor("2024-05-29", "H", nc.format(2117, "05/29/2024")
                                        .replace("MA VV", "MA DV 200-100"), "HJ 14",
                                        180, "DV", 200, 100)]},
            # entered on the next sitting, which has a journal of its own
            "HB1292": {"events": [floor("2024-05-30", "H", nc.format(2179, "05/30/2024"),
                                        "HJ 14", 181)]},
            # the same, at a page inside the sitting's own: stays
            "HB468": {"events": [floor("2024-05-30", "H", nc.format(1525, "05/30/2024"),
                                       "HJ 14", 100)]},
            "HB4": {"events": [floor("2024-05-30", "H", otp, "HJ 15", 2)]},
            "HB5": {"events": [floor("2024-05-30", "H", otp, "HJ 15", 3)]},
            "HB6": {"events": [floor("2024-05-30", "H", otp, "HJ 15", 4)]}},
        "1997-1998": {
            "HB50": {"events": [floor("1997-05-28", "H", "PASSED VV; HJ70,P2010", "HJ 70")]},
            "HB51": {"events": [floor("1997-05-28", "H", "PASSED VV; HJ70,P2011", "HJ 70")]},
            "HB52": {"events": [floor("1997-05-28", "H", "PASSED VV; HJ70,P2012", "HJ 70")]},
            "HB130": {"events": [floor("1997-05-29", "H", "HOUSE NONC WITH SEN AM REQ CONF "
                                       "COMM, REP LOZEAU MA; HJ70,P2037", "HJ 70", kind="")]},
            "SB122": {"events": [floor("1997-05-29", "H", "HOUSE ACCEDED TO REQ FOR CONF "
                                       "COMM, REP LOZEAU MA; HJ70,P2038", "HJ 70", kind="")]}},
        "2007-2008": {
            "SB1": {"events": [floor("2008-05-15", "S", otp, "SJ 18")]},
            "SB2": {"events": [floor("2008-05-15", "S", otp, "SJ 18")]},
            "SB3": {"events": [floor("2008-05-15", "S", otp, "SJ 18")]},
            "SB4": {"events": [floor("2008-05-21", "S", otp, "SJ 19")]},
            "SB5": {"events": [floor("2008-05-21", "S", otp, "SJ 19")]},
            "SB32": {"events": [floor("2008-05-21", "S", "Sen. Foster Moved Nonconcur with "
                                      "House Am{2501}(NT); Requests C of C, MA, VV",
                                      "SJ 18")]}},
    }
    root = Path(tempfile.mkdtemp())
    try:
        (root / "narratives.json").write_text(json.dumps(narr), encoding="utf-8")
        days = SD.load(root / "narratives.json")

        def bills(body, date):
            d = days.get((body, date))
            return [i.bill for i in d.items] if d else None
        want = {("H", "2024-05-23"): ["HB1", "HB2", "HB3", "HB1030", "HB1695",
                                      "HB1069", "HB1521", "HB1292"],
                ("H", "2024-05-24"): None, ("H", "2024-05-28"): None,
                ("H", "2024-05-29"): ["HB1593"],
                ("H", "2024-05-30"): ["HB4", "HB5", "HB6", "HB468"],
                ("H", "1997-05-28"): ["HB130", "HB50", "HB51", "HB52", "SB122"],
                ("H", "1997-05-29"): None,
                ("S", "2008-05-15"): ["SB1", "SB2", "SB3"],
                ("S", "2008-05-21"): ["SB32", "SB4", "SB5"]}
        got = {k: bills(*k) for k in want}
        assert got == want, "sittings are not as the journal holds them: " + "; ".join(
            f"{k[0]} {k[1]} has {got[k]}, want {want[k]}" for k in want if got[k] != want[k])
        moved = {i.bill: (i.entered, i.recess) for d in days.values() for i in d.items
                 if i.entered}
        assert moved == {"HB1695": ("2024-05-24", False), "HB1030": ("2024-05-24", False),
                         "HB1521": ("2024-05-28", False), "HB1069": ("2024-05-28", False),
                         "HB1292": ("2024-05-30", False), "HB130": ("1997-05-29", False),
                         "SB122": ("1997-05-29", False)}, (
            f"a moved row lost the day the docket enters it, or claims the docket "
            f"said recess: {moved}")
        assert days[("H", "2024-05-23")].ordered, "the sitting no longer reads in order"

        # The page: what the journal gives the bill that day is the sitting's.
        Item = SD.Item
        blank = {"type": "floor", "body": "H", "motion": "MA"}

        def item(bill, seq, raw, entered=None, recess=False, **e):
            ev = dict(blank, raw=raw, action=raw.split(":")[0], **e)
            it = Item(bill, "2013-2014", ev, seq)
            it.entered, it.recess = entered, recess
            return it
        acc = "House Accedes to Senate Request for C of C: MA VV"
        s389 = item("SB389", 1, "Rep Almy moved to accede to request for C of C; MA VV "
                    "(In recess of 5/15/14)", "2014-05-22", True, vote_kind="VV")
        s148 = item("SB148", 2, "Ought to Pass with Amendment #1730h: MA RC 170-113",
                    vote_kind="RC", yeas="170", nays="113")
        s148r = item("SB148", 3, acc + " [Recess of 6/5/13]", "2013-06-13", True,
                     vote_kind="VV")
        s19 = item("SB19", 4, acc + " [06/05/13]", "2013-06-12", False, vote_kind="VV")
        day = SD.Day("H", "2014-05-15", [s389, s148, s148r, s19])
        # As journal_days reads them from HJ044 and HJ049: the journal's own
        # tally for SB 148 is 166-119, so only the one-motion rule places it.
        speech = [{"bill": "SB389", "side": "for", "names": ["Burt", "Wright"],
                   "tally": (110, 177)},
                  {"bill": "SB389", "side": "against", "names": ["Beaudoin"],
                   "tally": (219, 72)},
                  {"bill": "SB148-FN", "side": "against",
                   "names": ["William O'Brien", "Tucker"], "tally": (166, 119)}]
        narrative = {"attributions": speech, "unanimous_consent": [],
                     "debates": [{"bill": "SB389", "speeches": [
                         ("Rep. Burt", "I rise in support of the amendment.")]}]}
        (root / "site").mkdir()
        html, _ = BSP.render(day, narrative, {}, {}, BSP.Members(root / "site"), shell.E)
        import html as H
        cards = {re.search(r'class="sbill">([^<]+)<', c).group(1):
                 H.unescape(re.sub(r"<[^>]+>", " ", c))
                 for c in html.split('<article class="sitem">')[1:]}
        assert not re.search(r"Burt|Wright|Beaudoin|Spoke|spoke", cards["SB 389"]), (
            "SB 389's accession, done in recess with no debate, is drawn with the "
            f"speeches on its floor amendments: {cards['SB 389'][:300]!r}")
        assert re.search(r"Spoke against the motion\s+Rep\. William O'Brien\s*,\s*"
                         r"Rep\. Tucker", cards["SB 148"]) \
            and "Also spoke" not in cards["SB 148"], (
            "SB 148's speakers were pushed off the roll call they spoke on by the "
            f"recess row beside it: {cards['SB 148'][:400]!r}")
        assert "Done in the recess of this sitting" in cards["SB 389"] and \
            "Printed in the journal with this sitting" in cards["SB 19"] and \
            "recess" not in cards["SB 19"], (
            "a row the docket says was done in recess, or one placed only by the "
            "journal it cites, is not described as the record has it")
        tail = html.split("Also printed in the permanent journal")
        assert len(tail) == 2 and "I rise in support" in tail[1], (
            "a debate printed on SB 389 that day is drawn under its recess row "
            "rather than among the debates on no motion of the day")
        return "ok", ("unmarked recess days and rows on their sitting, in the "
                      "journal's order, the counted day, the pageless row and the "
                      "row inside the sitting's pages where they are; a recess "
                      "row claims no speech and displaces none")
    finally:
        shutil.rmtree(root, ignore_errors=True)


@check("session", "a sitting's page goes when its day does, never a term at once, "
       "and none is built ahead of today", needs=("build_session_pages",))
def _session_pages_pruned(BSP):
    """Correcting a date does not take its page down by itself.

    build_session_pages wrote a page per sitting and never removed one, so
    site/session/H/2026-09-19.html would have stayed on disk, deployed and
    linked after the row behind it was put right. It removes them now -- and,
    because a writer run on a subset destroys the rest, refuses to remove more
    than PRUNE_CEILING at once without --prune, which is what a narratives.json
    missing whole terms would ask of it. A day after the build is not built:
    the Senate enters rows up to ten days ahead of its sittings.
    """
    import datetime
    here = Path(".").resolve()
    if not (here / "bills.html").exists():
        return "skip", "no bills.html here to build a page from"
    root = Path(tempfile.mkdtemp())
    try:
        site = root / "site"
        (site / "session" / "S").mkdir(parents=True)
        shutil.copy2(here / "bills.html", root / "bills.html")
        ahead = (datetime.date.today() + datetime.timedelta(days=12)).isoformat()

        def floor(date):
            return {"date": date, "body": "S", "type": "floor",
                    "raw": "Ought to Pass, MA, VV", "action": "Ought to Pass",
                    "motion": "MA", "vote_kind": "VV"}
        (root / "narratives.json").write_text(json.dumps({"2025-2026": {
            "SB1": {"events": [floor("2026-02-19"), floor(ahead)]},
            "SB2": {"events": [floor("2026-03-05")]}}}), encoding="utf-8")
        base = "https://graniterecord.org"
        stale = ["2026-02-16"]
        for d in stale:
            (site / "session" / "S" / f"{d}.html").write_text("old", encoding="utf-8")
        (site / "sitemap.xml").write_text(
            '<?xml version="1.0"?><urlset>\n'
            + "".join(f"<url><loc>{base}/session/S/{d}.html</loc></url>\n"
                      for d in stale + ["2026-02-19"]) + "</urlset>", encoding="utf-8")

        def run(*extra):
            return _run([sys.executable, str(here / "build_session_pages.py"),
                         "--site", "site", "--base", base, "--body", "S", *extra],
                        cwd=root, capture_output=True, text=True, timeout=180)
        r = run()
        assert r.returncode == 0, "build_session_pages: " + (r.stderr or r.stdout)[-300:]
        pages = sorted(p.stem for p in (site / "session" / "S").glob("*.html"))
        assert pages == ["2026-02-19", "2026-03-05"], (
            f"expected the two sittings and nothing else, got {pages}")
        sm = (site / "sitemap.xml").read_text(encoding="utf-8")
        assert "2026-02-16" not in sm, "the removed day is still in sitemap.xml"
        assert ahead not in sm and "after today not built" in r.stdout, (
            "a day after the build was published, or skipped without saying so")

        many = [f"2001-01-{n:02d}" for n in range(1, BSP.PRUNE_CEILING + 3)]
        for d in many:
            (site / "session" / "S" / f"{d}.html").write_text("old", encoding="utf-8")
        r = run()
        left = len(list((site / "session" / "S").glob("*.html")))
        assert r.returncode != 0 and "REFUSED" in (r.stderr + r.stdout) \
            and left == 2 + len(many), (
            f"{len(many)} removals at once were not refused, or a refusal "
            f"still removed pages ({left} left)")
        r = run("--prune")
        left = sorted(p.stem for p in (site / "session" / "S").glob("*.html"))
        assert r.returncode == 0 and left == ["2026-02-19", "2026-03-05"], (
            f"--prune did not remove the {len(many)} stale pages: {left[:4]}")
        return "ok", (f"a gone day's page and sitemap entry are removed; more "
                      f"than {BSP.PRUNE_CEILING} at once is refused without "
                      "--prune; a day after today is not built")
    finally:
        shutil.rmtree(root, ignore_errors=True)


# The House's leave list of 11 March 2026 (journals/2026/HJ 07 March 11,
# 2026.txt, LEAVES OF ABSENCE) and of 7 January 2026 (HJ 01, the same block),
# with the ballots RollCallHistory.txt holds for two of the members that day.
LEAVE_2026_03_11 = [
    (["Buco", "Cambrils", "Tom Dolan", "Ford", "Grote", "Gruber", "Molly Howard",
      "Love", "Geoffrey Smith", "Sofikitis", "Swanson", "Varney"], "illness"),
    (["Balboni", "Bennett", "DeDe-Poulin", "Girard", "Hicks", "Janigian", "Lovett",
      "Lundgren", "Tim Mannion", "Markell", "Notter", "Plamondon", "Jonathan Smith",
      "St. Clair", "Warden"], "important business"),
    (["Cornell"], "illness in the family"),
]
# Rep. Cornell, member 841, 11 March 2026: Excused on H-133 to H-172, then a
# Yea or Nay on every roll call from H-173 to H-188.
BALLOTS_CORNELL = {**{n: "Not Voting/Excused" for n in range(133, 173)},
                   **{n: ("Yea" if n in (173, 174, 179, 180, 182, 185, 186, 188)
                          else "Nay") for n in range(173, 189)}}
# Rep. William Dolan, member 10784, on leave for 7 January 2026 ("the day,
# important business") and recorded Not Voting/Not Excused on all 31 roll
# calls that day.
BALLOTS_W_DOLAN = {n: "Not Voting/Not Excused" for n in range(1, 32)}


@check("session", "an excused or absent member's line says what the record says, "
       "and never why", needs=("build_session_pages", "shell"))
def _vote_category_text(BSP, shell):
    """Every full roll call told readers an Excused member was "excused in
    advance for the whole day -- illness, a death in the family, or other
    significant obligation".

    The ballots say otherwise: on 42% of House member-days with an Excused
    ballot, 1999-2026, the member voted on another question that day, and a
    declared conflict of interest is coded Excused too. Presiding said "one
    member presides ... and does not vote except to break a tie" over roll
    calls that record two; Not Excused said the member "left the chamber
    rather than vote". The sitting pages said everyone on the journal's leave
    list "were not in the chamber" -- and Rep. Cornell, on leave for 11 March
    2026, voted on sixteen roll calls that afternoon.

    So each line is attributed to the record, bans the claims the record
    contradicts and every reason word, and the sitting note is run on the real
    leave lists with the ballots that contradict the old wording beside them.
    The labels themselves are not checked: whether "Excused absence" and
    "Absent, not excused" should be renamed is the person's decision.
    """
    src = Path("app.js").read_text(encoding="utf-8")
    m = re.search(r"const OTHER=\[(.*?)\];", src, re.S)
    assert m, "app.js no longer defines OTHER, the vote categories' text"
    strs = re.findall(r'"((?:[^"\\]|\\.)*)"', m.group(1))
    assert len(strs) == 9 and strs[0::3] == [
        "Presiding", "Not Voting/Excused", "Not Voting/Not Excused"], (
        f"OTHER is not the three categories it was: {strs[0::3]}")
    labels, blurbs = strs[1::3], strs[2::3]
    FALSE = ("in advance", "for the whole day", "rather than vote",
             "left the chamber", "except to break a tie", "one member presides",
             "not in the chamber", "had not been excused")
    REASON = re.compile(r"\b(illness|business|death|family|weather|birth|sick)\b", re.I)
    for text in labels + blurbs:
        bad = [p for p in FALSE if p in text.lower()]
        assert not bad, f"a vote category states what the record contradicts ({bad}): {text!r}"
        assert not REASON.search(text), f"a vote category gives a reason: {text!r}"
        assert not re.search(r'[<&"]', text), (
            f"a vote category string is inserted unescaped and holds < & or \": {text!r}")
    assert all(b.startswith("Recorded as") for b in blurbs), (
        "each category's explanation must attribute itself to the record: "
        + " | ".join(b[:40] for b in blurbs))
    assert "part of a day" in blurbs[1] and "single vote" in blurbs[1], (
        "the Excused explanation no longer says an excuse can cover part of a "
        "day or a single vote")

    # The ballots are the evidence the note has to allow for.
    assert any(v in ("Yea", "Nay") for v in BALLOTS_CORNELL.values()) and \
        any(v == "Not Voting/Excused" for v in BALLOTS_CORNELL.values())
    assert set(BALLOTS_W_DOLAN.values()) == {"Not Voting/Not Excused"}
    root = Path(tempfile.mkdtemp())
    try:
        members = BSP.Members(root)
        for leave in (LEAVE_2026_03_11,
                      [(["Aylward", "Bordes", "Cahill", "William Dolan"], "important business")]):
            narr = {"absences": [{"names": names, "when": "the day", "why": why}
                                 for names, why in leave]}
            html = BSP.absences_html(narr, "H", members, shell.E)
            names = [n for g, _ in leave for n in g]
            text = re.sub(r"<[^>]+>", " ", html)
            missing = [n for n in names if n not in text]
            assert not missing, f"the leave list lost {missing}"
            assert f"records {len(names)} member" in text, (
                f"the note's count is not the {len(names)} names it lists")
            assert not REASON.search(text), (
                "a sitting page gives the reason a member was away: "
                + REASON.search(text).group(0))
            assert "not in the chamber" not in text and \
                "may still have voted" in text and "does not always agree" in text, (
                "the leave note says members on leave were absent, which Rep. "
                "Cornell's ballots of 11 March 2026 contradict, or hides that the "
                "roll call and the journal disagree, as on William Dolan's of "
                "7 January 2026")
        return "ok", ("the three categories are attributed to the record, with "
                      "no contradicted claim and no reason; the leave note names "
                      "members only and allows for the ballots that vote or "
                      "disagree")
    finally:
        shutil.rmtree(root, ignore_errors=True)


